def deprecatedMethod(method: str, instead: str | None = None, docs: str | None = None) {
    try {
        msg = "DEPRECATED method `" + method + "`.";
        if instead {
            msg += " Use `" + instead + "` instead.";
        }
        msg += " This method will be removed in a future release.";
        print(msg);
        if docs {
            print("For more information about usage see " + docs);
        }
    } except Exception {}
}

glob:pub default = deprecatedMethod;

