import from .config { GET, POST, DELETE, PUT }

obj ArticleBody {
    has title: str,
        description: str,
        body: str,
        tagList: list[str];
}

obj ArticleAPIBody {
    has article: ArticleBody;
}

def:pub getArticles(query: str, signal: object) -> object {
    return GET(f"/articles{query}", signal);
}

def:pub postArticle(body: ArticleAPIBody) -> object {
    return POST("/articles", body);
}

def:pub getArticle(slug: str) -> object {
    return GET(f"/articles/{slug}");
}

def:pub putArticle(slug: str, body: ArticleAPIBody) -> object {
    return PUT(f"/articles/{slug}", body);
}

def:pub deleteArticle(slug: str) -> object {
    return DELETE(f"/articles/{slug}");
}

