import from "antd-mobile" { Toast }
import from "react" { useEffect, useRef }

def:pub ToastLoading(loading: bool = False, title: str = "加载中…") -> JsxElement {
    close = useLoading(loading=loading, title=title);
    can with [close] exit { close(); }
    <></>
}

def:pub useLoading(loading: bool = False, title: str = "加载中…") -> Callable[[], None] {
    toastRef = useRef(None);
    useEffect(lambda {
        if loading {
            toastRef.current = Toast.show({"icon": "loading", "duration": 0, "content": title});
        } else {
            if toastRef.current {
                toastRef.current.close();
            }
        }
    }, [loading, title]);
    return lambda {
        if toastRef.current {
            toastRef.current.close();
        }
    };
}

