import from shared.lib.Queue { Queue }
import from shared.lib.browser { logInfo }

def createEventQueueHandler(
    store: Store,
    reducer: Callable[[object, object], object]
) -> Callable[[Queue], None] {
    def queueHandler(eventQueue: Queue) {
        state = store.getState();
        while not eventQueue.isEmpty() {
            event = eventQueue.dequeue();
            logInfo(event);
            state = reducer(state, event);
        }
        action: dict[str, object] = {"type": actionTypes.SET_STATE, "state": state};
        store.dispatch(action);
    }
    return queueHandler;
}

