# from: mfscpayload-690__moviemonk-ai::scripts/load-env.js
import os;
import re;
import from pathlib { Path }

def:pub loadEnv() -> dict[str, str] {
    env: dict[str, str] = dict(os.environ);
    base = Path(str(__file__)).resolve().parent.parent;
    env_paths: list[Path] = [base / ".env.local", base / ".env"];
    for env_path in env_paths {
        if env_path.exists() {
            try {
                content = env_path.read_text(encoding="utf-8");
                for line in content.split("\n") {
                    m = re.match(r"^\s*([\w.-]+)\s*=\s*(.*)?\s*$", line);
                    if m is not None {
                        key = m.group(1);
                        value = m.group(2) or "";
                        if value.startswith('"') and value.endswith('"') {
                            value = value[1:-1];
                        } elif value.startswith("'") and value.endswith("'") {
                            value = value[1:-1];
                        }
                        env[key] = value.strip();
                    }
                }
            } except OSError as err {
                print(f"[SEO Warning] Failed to read environment file at {env_path}: {err}");
            }
        }
    }
    return env;
}

