def:pub convertToDate(datetime: str) -> str {
    parts = [int(x) for x in datetime.split("T")[0].split("-")];
    year = parts[0];
    month = parts[1];
    day = parts[2];
    return f"{months[month - 1]} {day}, {year}";
}

