import from "react" { useRef, useState, useCallback, useEffect }

glob FLUSH_INTERVAL_MS: int = 50;

obj StreamBufferResult {
    has append: Callable[[str], None];
    has reset: Callable[[], None];
    has getText: Callable[[], str];
    has displayText: str;
}

def:pub useStreamBuffer(isActive: bool) -> StreamBufferResult {
    bufferRef = useRef("");
    pendingRef = useRef("");
    timerRef = useRef(None);
    displayState = useState("");
    displayText = displayState[0];
    setDisplayText = displayState[1];
    flush = useCallback(lambda () {
        if pendingRef.current {
            bufferRef.current = (bufferRef.current as str) + (pendingRef.current as str);
            pendingRef.current = "";
        }
        setDisplayText(bufferRef.current as str);
        timerRef.current = None;
    }, []);
    append = useCallback(lambda (text: str) {
        pendingRef.current = (pendingRef.current as str) + text;
        if not timerRef.current {
            timerRef.current = setTimeout(flush, FLUSH_INTERVAL_MS);
        }
    }, [flush]);
    reset = useCallback(lambda () {
        bufferRef.current = "";
        pendingRef.current = "";
        if timerRef.current {
            clearTimeout(timerRef.current);
            timerRef.current = None;
        }
        setDisplayText("");
    }, []);
    getText = useCallback(lambda () -> str {
        return (bufferRef.current as str) + (pendingRef.current as str);
    }, []);
    useEffect(lambda () {
        if not isActive and timerRef.current {
            clearTimeout(timerRef.current);
            timerRef.current = None;
            if pendingRef.current {
                bufferRef.current = (bufferRef.current as str) + (pendingRef.current as str);
                pendingRef.current = "";
            }
            setDisplayText(bufferRef.current as str);
        }
    }, [isActive]);
    useEffect(lambda () {
        return lambda () {
            if timerRef.current {
                clearTimeout(timerRef.current);
            }
        };
    }, []);
