def build_template_props(name: str, custom_data: dict[str, object], extra: dict[str, object]) -> dict[str, object] {
    props: dict[str, object] = {"name": name};
    for (k, v) in extra.items() {
        props[k] = v;
    }
    for (k, v) in custom_data.items() {
        props[k] = v;
    }
