async def:pub sendTestEmail(form_data: dict[str, str]) -> dict[str, bool | str] {
    try {
        to = form_data.get("to", "");
        template = form_data.get("template", "");
        subject = form_data.get("subject", "");
        user_name = form_data.get("userName", "") or "Test User";
        custom_data_str = form_data.get("customData", "");
        custom_data: dict[str, object] = {};
        if custom_data_str {
            try {
                custom_data = json.loads(custom_data_str) as dict[str, object];
            } except json.JSONDecodeError {
                return {"success": False, "error": "Invalid JSON in custom data"};
            }
        }
        email_template: object;
        default_subject: str;
        match template {
            case "verify-email":
                email_template = VerifyEmail(build_template_props(user_name, custom_data, {"verifyUrl": "https://example.com/verify?token=test123"}));
                default_subject = "Verify your email address";
            case "reset-password":
                email_template = ResetPassword(build_template_props(user_name, custom_data, {"resetUrl": "https://example.com/reset?token=test123"}));
                default_subject = "Reset your password";
            case "two-factor":
                email_template = TwoFactor(build_template_props(user_name, custom_data, {"code": "123456"}));
                default_subject = "Your verification code";
            case "welcome":
                email_template = Welcome(build_template_props(user_name, custom_data, {"loginUrl": "https://example.com/login"}));
                default_subject = "Welcome to our platform!";
            case _:
                return {"success": False, "error": "Invalid template selected"};
        }
        final_subject = subject or default_subject;
        html = await render(email_template) as str;
        await sendEmail({"to": to, "subject": final_subject, "html": html});
        return {"success": True};
    } except Exception as e {
        print(f"Failed to send test email: {str(e)}");
        return {"success": False, "error": str(e)};
    }
}

