};

def textVariants(
    size: str | None = None,
    weight: str | None = None,
    color: str | None = None,
    align: str | None = None,
    truncate: bool = False,
    noWrap: bool = False,
    muted: bool = False,
) -> str {
    return cn(
        "text",
        f"text-size-{size}" if size is not None else "",
        f"text-weight-{weight}" if weight is not None else "",
        f"text-color-{color}" if color is not None else "",
        f"text-align-{align}" if align is not None else "",
        "truncate" if truncate else "",
        "whitespace-nowrap" if noWrap else "",
        "text-muted-foreground" if muted else "",
    );
}

def:pub Text(
    as_: str = "p",
    size: str = "md",
    weight: str | None = None,
    color: str = "neutral",
    align: str | None = None,
    truncate: bool = False,
    lineClamp: str | None = None,
    muted: bool = False,
    noWrap: bool = False,
    uppercase: bool = False,
    lowercase: bool = False,
    capitalize: bool = False,
    italic: bool = False,
    underline: bool = False,
    strikethrough: bool = False,
    className: str | None = None,
    children: object | None = None,
    ref: Ref[HTMLParagraphElement] = Ref(),
    props: dict[str, object] = {},
) -> JsxElement {
    truncateVal = truncate and not lineClamp;
    variantColor = None if muted else color;
    classes = cn(
        textVariants(size=size, weight=weight, color=variantColor, align=align, truncate=truncateVal, noWrap=noWrap, muted=muted),
        TEXT_LINE_CLAMP.get(lineClamp, "") if lineClamp else "",
        TEXT_TRANSFORMS["uppercase"] if uppercase else "",
        TEXT_TRANSFORMS["lowercase"] if lowercase else "",
        TEXT_TRANSFORMS["capitalize"] if capitalize else "",
        TEXT_DECORATIONS["italic"] if italic else "",
        TEXT_DECORATIONS["underline"] if underline else "",
        TEXT_DECORATIONS["strikethrough"] if strikethrough else "",
        className,
    );
    <@as_ ref={ref} data-slot="text" className={classes} {**props}>{children}</@as_>
}

