import from types { ContextProps, NeosContentNode, NeosData }

def:pub resolveCurrentNode(ctx: ContextProps, neosData: NeosData) -> NeosContentNode | None {
    if not ctx.currentNodeIdentifier {
        return None;
    }
    return resolveCurrentNodeRecursive(ctx.currentNodeIdentifier, neosData.node);
}

def:pub resolveCurrentNodeRecursive(currentNodeIdentifier: str, `node: NeosContentNode) -> NeosContentNode | None {
    if `node.identifier == currentNodeIdentifier {
        return `node;
    }
    if not `node.children {
        return None;
    }
    for child in `node.children {
        result = resolveCurrentNodeRecursive(currentNodeIdentifier, child);
        if result is not None {
            return result;
        }
    }
    return None;
}

