def useLazyRef(initialValFunc: Callable[[], object]) -> Ref[object] {
    ref: Ref[object] = Ref();
    if ref.current is None {
        ref.current = initialValFunc();
    }
    return ref;
}

def:pub useStore(s: Callable[[], object]) -> object {
    store = useLazyRef(s);
    return store.current as object;
}

