def:pub DraftPraise(praiseCount: int, className: str | None = None) -> JsxElement {
    has shownCount: int = 0;

    useEffect(lambda {
        if praiseCount == 0 {
            return lambda { };
        }
        shownCount = praiseCount;
        timer = setTimeout(lambda { shownCount = 0; }, VISIBLE_MS);
        return lambda { clearTimeout(timer); };
    }, [praiseCount]);

    if shownCount == 0 {
