obj GithubUserResponse {
    has data: GithubUserData;
}

obj GithubOrgsResponse {
    has data: list[Org];
}

def:pub All() -> JsxElement {
    has useravatar: str = "";
    has username: str = "";
    has orgs: list[Org] = [];

    can with entry {
        axios.all([
            axios.get("https://api.github.com/users/mzabriskie"),
            axios.get("https://api.github.com/users/mzabriskie/orgs")
        ]).then(lambda (results: list[object]) -> None {
            user = results[0] as GithubUserResponse;
            orgs_resp = results[1] as GithubOrgsResponse;
            console.log(user);
            useravatar = user.data.avatar_url;
            username = user.data.name;
            orgs = orgs_resp.data;
        });
    }

    <>
        <h1>axios.all</h1>
        <div>
            <h3>User</h3>
            <div className="row">
                <img id="useravatar" src={useravatar} className="col-md-1" />
                <div className="col-md-3">
                    <strong id="username">{username}</strong>
                </div>
            </div>
            <hr />
            <h3>Orgs</h3>
