obj I18n {
    has lang_key: str;
    has lang: Lang | None = None;

    def postinit {
        self.lang = langs.get(self.lang_key);
    }

    def get(id: str, params: list[str] | None = None) -> str {
        if self.lang is None {
            return id;
        }
        word = self.lang.get(id);
        if word is None {
            return id;
        }
        result: str = word;
        if params is not None {
            for i in range(len(params)) {
                result = result.replace(f"{{{i}}}", params[i]);
            }
        }
        return result;
    }
}

