def:pub createApiError(status: int, code: str, message: str) -> dict[str, int | str] {
    return {"status": status, "code": code, "message": message};
}

def _api_errors_unauthorized -> dict[str, int | str] {
    return createApiError(401, "UNAUTHORIZED", "Authentication required");
}

def _api_errors_forbidden(message: str = "Access denied") -> dict[str, int | str] {
    return createApiError(403, "FORBIDDEN", message);
}

def _api_errors_notFound(resource: str = "Resource") -> dict[str, int | str] {
    return createApiError(404, "NOT_FOUND", f"{resource} not found");
}

def _api_errors_validation(message: str) -> dict[str, int | str] {
    return createApiError(422, "VALIDATION_ERROR", message);
}

def _api_errors_internal(message: str = "An unexpected error occurred") -> dict[str, int | str] {
    return createApiError(500, "INTERNAL_ERROR", message);
}

glob:pub API_ERRORS: dict[str, Callable] = {
    "unauthorized": _api_errors_unauthorized,
    "forbidden": _api_errors_forbidden,
    "notFound": _api_errors_notFound,
    "validation": _api_errors_validation,
    "internal": _api_errors_internal,
};

