import from "convex/nextjs" { fetchQuery }
import from "@convex/_generated/api" { api }

glob:pub alt: str = "Shared via Silong";

glob:pub size: dict[str, int] = {"width": 1200, "height": 630};

glob:pub contentType: str = "image/png";

async def:pub OG(props: dict[str, object]) -> object {
    resolvedParams = await props["params"] as dict[str, str];
    id = resolvedParams["id"];
    title = "Shared on Silong";
    icon = "📄";
    cover: str | None = None;
    try {
        p = await fetchQuery(api.pages.getPublicShare, {"id": id});
        if p is not None {
            page = p as dict[str, object];
            title = (page.get("title") or "Untitled") as str;
            icon = (page.get("icon") or "📄") as str;
            pageCover = page.get("cover");
            if pageCover is not None {
                cover = pageCover as str;
            }
        }
    } except Exception {
        _ = None;
    }
    if icon.startswith("lucide:") {
        displayIcon = "📄";
    } else {
        displayIcon = icon.split("?")[0];
    }
    if cover is not None and cover.startswith("linear-gradient") {
        bg = cover;
    } else {
        bg = "linear-gradient(135deg, #0f172a, #1e293b)";
    }
    return new(ImageResponse, <div style={{"width": "100%", "height": "100%", "display": "flex", "flexDirection": "column", "justifyContent": "space-between", "padding": "80px", "fontFamily": "system-ui, -apple-system, Segoe UI, Roboto, Inter, sans-serif", "background": bg, "color": "white"}}><div style={{"display": "flex", "alignItems": "center", "gap": 16}}><div style={{"fontSize": 28, "opacity": 0.7, "letterSpacing": 4, "textTransform": "uppercase"}}>Silong</div></div><div style={{"display": "flex", "flexDirection": "column", "gap": 24}}><div style={{"fontSize": 120, "lineHeight": 1}}>{displayIcon}</div><div style={{"fontSize": 72, "fontWeight": 700, "lineHeight": 1.05, "letterSpacing": -1, "maxWidth": "90%", "display": "-webkit-box", "WebkitBoxOrient": "vertical", "WebkitLineClamp": 3, "overflow": "hidden"}}>{title}</div></div><div style={{"fontSize": 24, "opacity": 0.6}}>silong.rahmanef.com</div></div>, size);
}

