    def handleEmailChange(event: ChangeEvent) {
        email = event.target.value;
    }

    def handlePasswordChange(event: ChangeEvent) {
        password = event.target.value;
    }

    def handlePasswordConfirmationChange(event: ChangeEvent) {
        passwordConfirmation = event.target.value;
    }

    def handleSubmitClick(event: MouseEvent) {
        event.preventDefault();
        if isSignInForm {
            return;
        }
        if password != passwordConfirmation {
            return;
        }
    }

    <form className="login-form">
        <div className="form-field">
            <label htmlFor="email">Email</label>
            <input
                id="email"
                type="email"
                name="email"
                className="email"
                value={email}
                onChange={handleEmailChange}
                placeholder="Type your email"
            />
        </div>
        <div className="form-field">
            <label htmlFor="password">Password</label>
            <input
                id="password"
                type="password"
                name="password"
                className="password"
                value={password}
                onChange={handlePasswordChange}
                placeholder="Type your password"
            />
        </div>
        {if not isSignInForm {
            <div className="form-field">
                <label htmlFor="repeatPassword">Confirm Password</label>
                <input
                    id="repeatPassword"
                    type="password"
                    name="repeat-password"
                    className="password"
                    value={passwordConfirmation}
                    onChange={handlePasswordConfirmationChange}
                    placeholder="Type your password"
                />
            </div>
        }}
        <div className="form-buttons">
            <button onClick={handleSubmitClick}>
                {"Sign in" if isSignInForm else "Sign up"}
            </button>
        </div>
    </form>
}

