async def:pub editBlog(payload: EditBlogType) -> BlogType {
    blog = payload.blog;
    values = payload.values;
    editedBlog = await pb.collection("blogs").update(
        blog.id,
        {
            "title": (values.title if values.title != "" else blog.title),
            "content": (values.content if values.content != "" else blog.content),
            "image": (values.image if values.image != "" else blog.image),
        },
        {"expand": "user"}
    );
    return editedBlog as BlogType;
}

