async def:pub default(req: NextApiRequest, res: NextApiResponse) -> object | None {
    method = req.method;
    body = req.body as dict[str, object];
    response: object | None = None;
    switch method {
        case "GET":
            res.json({"method": "GET", "endpoint": "Users"});
            break;
        case "PUT":
            response = await updateProperty(body);
            return res.json(response) as object;
        case "POST":
            response = await createProperty(body);
            return res.json(response) as object;
        case "DELETE":
            response = await removeProperty(body);
            return res.json(response) as object;
        default:
            res.setHeader("Allow", ["GET", "POST"]);
            res.status(405).end(f"Method {method} Not Allowed");
            break;
    }
    return None;
}

