def parseLit(v: str) -> any {
    t = v.strip();
    if (t.lower() == "true") {
        return true;
    }
    if (t.lower() == "false") {
        return false;
    }
    if (t.lower() == "null") {
        return None;
    }
    if ((t.startswith("\"") and t.endswith("\"")) or (t.startswith("'") and t.endswith("'"))) {
        return t[1:-1];
    }
    n = Number(t);
    return (n if not isNaN(n) else t);
}

def splitArgs(s: str) -> list[str] {
