    cur = "";
    depth = 0;
    inStr = false;
    strCh = "";
    for c in s {
        if (((c == "\"") or (c == "'")) and not inStr) {
            inStr = true;
            strCh = c;
            cur += c;
            continue;
        }
        if ((c == strCh) and inStr) {
            inStr = false;
            strCh = "";
            cur += c;
            continue;
        }
        if inStr {
            cur += c;
            continue;
        }
