        # | if (c === '(') depth++;
        # JS2JAC-HOLE[E7215] Unsupported expression in body: UpdateExpression:
        # | if (c === ')') depth--;
        if ((c == ",") and (depth == 0)) {
            args.append(cur.strip());
            cur = "";
        }
        else {
            cur += c;
        }
    }
    if cur.strip() {
        args.append(cur.strip());
    }
    return args;
}

