import from "react" { useEffect }

def:pub useScrollBehaviour(deps: list[object]) -> Ref[HTMLElement] {
    container: Ref[HTMLElement] = Ref();
    useEffect(lambda -> None {
        if not container.current {
            return;
        }
        current = container.current as HTMLElement;
        current.scrollTop = current.scrollHeight;
    }, deps);
    return container;
}

