# from: DaniloNovakovic__chrome-dynamic-bookmarks::background/requestHandlers/addBookmarkNodeHandler.ts
import from "@/shared/constants/responseTypes" { default as responseTypes }
import from "@/shared/lib/browser" { createBookmarkNode }

def addBookmarkNodeHandler(
    message: dict[str, object],
    sendResponse: Callable[[dict[str, object]], None]
) {
    data = message.get("data");
    if not data or not isinstance(data, dict) {
        sendResponse({"type": responseTypes.ERROR, "message": "Missing request data"});
        return;
    }
    createBookmarkNode(
        data,
        lambda (errMsg: str | None, createdNode: dict[str, object]) {
            if errMsg {
                sendResponse({"type": responseTypes.ERROR, "message": errMsg});
            } else {
                sendResponse({
                    "type": responseTypes.SUCCESS,
                    "message": f"Successfully created bookmark '{createdNode['title']}'",
                    "data": createdNode
                });
            }
        }
    );
}

