def parseTime(value: object) -> float {
    if ((not isinstance(value, str)) or (len(value.strip()) == 0)) {
        return 0.0;
    }
    parsed = Date.parse(value);
    return (0.0 if Number.isNaN(parsed) else parsed);
}

