type MessageResponse = dict[str, object];
type OnMessageResponseFn = Callable[[MessageResponse], None];

def:pub sendMessage[T](type: str, data: T, onResponse: OnMessageResponseFn) {
    browser = getCurrentBrowser();
    req = {"type": type, "data": data};

    def handleResponse(res: MessageResponse | None = None) {
        if res is None {
            res = {};
        }
        if "type" not in res {
            res["type"] = responseTypes["ERROR"];
        }
        if "message" not in res {
            if res["type"] == responseTypes["SUCCESS"] {
                res["message"] = "Success - Operation completed!";
            } else {
                res["message"] = "Oops! Something went wrong! \n        Help us improve your experience by sending an error report.";
            }
        }
        logInfo("response", res);
        onResponse(res);
    }

    browser.runtime.sendMessage(req, handleResponse);
}

