# from: damiansire__web-vaccine-tracker::lib/milestones.ts
glob MS_PER_DAY = 86400000;

glob:pub FULLY_VACCINATED_MILESTONE_PCT = 50;

def:pub dateAtThreshold(rows: list[list[object]], fields: list[str], field: str, thresholdPct: float) -> str | None {
    dateIdx = fields.index("date");
    valueIdx = fields.index(field);
    for row in rows {
        value = row[valueIdx];
        if (isinstance(value, (int, float)) and (value >= thresholdPct)) {
            date = row[dateIdx];
            return (date if isinstance(date, str) else None);
        }
    }
    return None;
}

