import from "@/components/ui" { Button, DialogBody, DialogClose, DialogContent, DialogFooter, DialogHeader, DialogTitle }
import from "@/features/groups/lib/actions" { removeMember }
import from "next/navigation" { useRouter }

def:pub MemberCardDeleteDialog(
    onParentClose: Callable[[], None],
    onDialogClose: Callable[[], None],
    userId: str,
    groupId: str,
) -> JsxElement {
    has isLoading: bool = False;
    router = useRouter();

    async def handleDelete() {
        if isLoading {
            return;
        }
        isLoading = True;
        if not groupId or not userId {
            return;
        }
        result = await removeMember(groupId, userId);
        if not result.ok {
            alert("Something went wrong, please try again");
            onDialogClose();
            onParentClose();
            isLoading = False;
        } else {
            alert("Successfully deleted!");
            onDialogClose();
            onParentClose();
            isLoading = False;
            router.refresh();
        }
    }

    <DialogContent>
        <DialogHeader>
            <DialogTitle>Delete Member</DialogTitle>
        </DialogHeader>
        <DialogBody>
            <p>Are you sure you want to delete the member?</p>
        </DialogBody>
        <DialogFooter>
            <DialogClose asChild>
                <Button type="button" variant="cancel" size="sm" onClick={onParentClose}>
                    Cancel
                </Button>
            </DialogClose>
            <Button variant="danger" size="sm" onClick={handleDelete} disabled={isLoading}>
                Delete
            </Button>
        </DialogFooter>
    </DialogContent>
}

