# from: sun-empire-solutions__meets-app::hooks/useLocalAudioToggle.ts
import from "react" { useCallback }
import from "twilio-video" { LocalAudioTrack, Room }
import from .useIsTrackEnabled { useIsTrackEnabled }
import from ..context { useTwilioContext }
import from .useTracksSettings { useTracksSettings }

type AudioTrackType = LocalAudioTrack | None;

def:pub useLocalAudioToggle -> list[bool | Callable[[], None]] {
    ctx = useTwilioContext();
    audio_track: AudioTrackType = ctx["audioTrack"] as AudioTrackType;
    get_local_audio_track = ctx["getLocalAudioTrack"] as Callable[[], Awaitable[LocalAudioTrack]];
    room: Room | None = ctx["room"] as Room | None;
    remove_local_audio_track = ctx["removeLocalAudioTrack"] as Callable[[], None];
    local_participant = room.localParticipant if room else None;
    is_enabled = useIsTrackEnabled(audio_track);
    settings = useTracksSettings();
    save_audio_settings = settings["saveAudioSettings"] as Callable[[bool], None];

    async def publish_local_audio {
        try {
            track = await get_local_audio_track();
            save_audio_settings(True);
            if local_participant {
                local_participant.publishTrack(track, {"priority": "low"});
            }
        } except Exception as error {
            console.log(error);
        }
    }

    toggle_audio_enabled = useCallback(lambda -> None {
        if audio_track {
            if local_participant {
                local_track_publication = local_participant.unpublishTrack(audio_track);
                local_participant.emit("trackUnpublished", local_track_publication);
            }
            remove_local_audio_track();
            save_audio_settings(False);
            return;
        }
        publish_local_audio();
    }, [audio_track]);

    return [is_enabled, toggle_audio_enabled];
}

