import re;
import unicodedata;

def:pub slugify(name: str) -> str {
    s = unicodedata.normalize("NFD", name);
    s = re.sub(r"[\u0300-\u036f]", "", s);
    s = s.lower().strip();
    s = re.sub(r"[^a-z0-9]+", "-", s);
    s = re.sub(r"^-+|-+$", "", s);
    return s;
}

