import from "../config" { iconList, windowFeatures }

def:pub Icon(
    id: str,
    shareData: dict[str, str],
    onClose: Callable[[], None],
    onClick: Callable[[], None] | None = None,
    noReferer: bool = False
) -> JsxElement {
    has hover: bool | None = None;

    entry = iconList[id];
    title = entry["title"] as str;
    path = entry["path"] as JsxElement;
    color = entry["color"] as str;
    urlFn = entry["url"] as Callable[[str, str, str], str];
    viewBox = "0 0 24 24";
    if "viewBox" in entry {
        viewBox = entry["viewBox"] as str;
    }

    def handleOnButtonClicked() {
        if onClick {
            onClick();
        }
        uri = urlFn(
            encodeURIComponent(shareData["link"]),
            encodeURIComponent(shareData["textToShare"]),
            encodeURIComponent(shareData["linkTitle"])
        );
        features = f"{windowFeatures}{' noreferer' if noReferer else ''}";
        window.open(uri, id, features);
        onClose();
    }

    <button
        onClick={handleOnButtonClicked}
        onMouseEnter={lambda (_e: MouseEvent) { hover = True; }}
        onMouseLeave={lambda (_e: MouseEvent) { hover = False; }}
        aria-label={id}
        style={{
            "width": "100%",
            "height": "auto",
            "cursor": "pointer",
            "border": "none",
            "background": "none"
        }}
    >
        <div
            style={{
                "borderRadius": "0.5rem",
                "height": "auto",
                "background": color,
                "scale": "1.03" if hover else "none",
                "boxShadow": "0 0 12px rgba(0,0,0,0.2)" if hover else "none",
                "padding": "0.75rem",
                "paddingBottom": "calc(0.5rem + 1px)"
            }}
        >
            <svg fill="white" viewBox={viewBox}>{path}</svg>
        </div>
        <span
            style={{
                "display": "block",
                "marginTop": "0.3rem",
                "fontSize": "0.75rem"
            }}
        >
            {title}
        </span>
    </button>
}

