obj TabPanel {
    has id: str;
    has title: str;
    has content: object;
}

def:pub Tabs(
    tabs: list[TabPanel],
    defaultActiveTab: str | None = None,
    onTabChange: Callable[[str], None] | None = None,
    className: str = "",
) -> JsxElement {
    has activeTab: str = defaultActiveTab if defaultActiveTab else (tabs[0].id if len(tabs) > 0 else "");

    def handle_tab_click(tabId: str) {
        activeTab = tabId;
        if onTabChange {
            onTabChange(tabId);
        }
    }

    <section className={f"tabs {className}"}>
        <menu role="tablist">
            {for tab in tabs {
                <Button
                    key={tab.id}
                    role="tab"
                    aria-controls={tab.id}
                    aria-selected={activeTab == tab.id}
                    onClick={lambda { handle_tab_click(tab.id); }}
                >
                    {tab.title}
                </Button>
            }}
        </menu>
        {for tab in tabs {
            <article
                key={tab.id}
                role="tabpanel"
                id={tab.id}
                hidden={activeTab != tab.id}
            >
                {tab.content}
            </article>
        }}
    </section>
}

