obj ReduxStore {
    has asyncReducers: dict[str, object] = {};
}

def configureStore(initialState: dict[str, object] = {}) -> ReduxStore {
    middlewares: list[object] = [];
    enhancers = [applyMiddleware(*middlewares)];
