def _validatedLastData(raw: object) -> list[LastDataRow] {
    assertLastDataRows(raw);
    return raw as list[LastDataRow];
}

def _dataDir -> str {
    return os.path.dirname(os.path.abspath(__file__));
}

def _readJsonFile(path: str) -> object {
    fh = open(path, encoding="utf-8");
    data = json.load(fh);
    fh.close();
    return data;
}

glob:pub manifest: Manifest = manifestJson as Manifest;
glob:pub isoCodes: list[IsoCodeEntry] = isoCodesJson as list[IsoCodeEntry];
glob:pub lastData: list[LastDataRow] = _validatedLastData(lastDataJson);

async def:pub loadCountry(countryName: str) -> CountryFile | None {
    slug: str = slugify(countryName) as str;
    try {
        path = os.path.join(_dataDir(), "countries", f"{slug}.json");
        data = _readJsonFile(path);
        return data as CountryFile;
    } except Exception as e {
        print(f'[data/loader] no se pudo cargar el país "{countryName}" (slug "{slug}"): {str(e)}');
        return None;
    }
}

async def:pub loadCountrySources(countryName: str) -> SourcesFile {
    slug: str = slugify(countryName) as str;
    try {
        path = os.path.join(_dataDir(), "sources", f"{slug}.json");
        data = _readJsonFile(path);
        return data as SourcesFile;
    } except Exception as e {
        print(f'[data/loader] no se pudieron cargar las fuentes de "{countryName}" (slug "{slug}"): {str(e)}');
        return {"sources": []};
    }
}

