import from "zustand" { create }
import from "zustand/middleware" { persist }

glob DEFAULT_NAV_ORDER: list[str] = ["/schedule", "/notes", "/tasks", "/create"];

def migrateNavOrder(persisted: object, version: int) -> object {
    state = persisted as dict[str, object];
    if version < 4 {
        order = state.get("navOrder", DEFAULT_NAV_ORDER) as list[str];
        order = [p for p in order if p != "/habits"];
        order = ["/create" if p == "/docs" else p for p in order];
        state = {**state, "navOrder": order};
    }
    return state;
}

def sidebarNavStoreInitializer(setFn: Callable[[object], None]) -> dict[str, object] {
    def setNavOrder(order: list[str]) -> None {
        setFn({"navOrder": order});
    }
    def resetToDefault() {
        setFn({"navOrder": DEFAULT_NAV_ORDER});
    }
    return {
        "navOrder": DEFAULT_NAV_ORDER,
        "setNavOrder": setNavOrder,
        "resetToDefault": resetToDefault,
    };
}

glob useSidebarNavStore = create()(persist(sidebarNavStoreInitializer, {"name": "sidebar-nav-order", "version": 4, "migrate": migrateNavOrder}));

