def:pub buttonVariants(variant: str | None = None, size: str | None = None) -> str {
    base = "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0";
    v = variant if variant is not None else "default";
    s = size if size is not None else "default";
    variant_classes = {
        "default": "bg-primary text-primary-foreground shadow hover:bg-primary/90",
        "destructive": "bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90",
        "outline": "border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground",
        "secondary": "bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80",
        "ghost": "hover:bg-accent hover:text-accent-foreground",
        "link": "text-primary underline-offset-4 hover:underline",
    };
    size_classes = {
        "default": "h-9 px-4 py-2",
        "sm": "h-8 rounded-md px-3 text-xs",
        "lg": "h-10 rounded-md px-8",
        "icon": "h-9 w-9",
    };
    return cn(base, variant_classes.get(v, ""), size_classes.get(s, "")) as str;
}

def:pub Button(className: str | None = None, variant: str | None = None, size: str | None = None, asChild: bool = False, ref: Ref[HTMLButtonElement] = Ref(), props: dict[str, object] | None = None) -> JsxElement {
    extra = props if props is not None else {};
    merged = cn(buttonVariants(variant, size), className);
    if asChild {
        return <Slot className={merged} ref={ref} {**extra} />;
    }
    return <button className={merged} ref={ref} {**extra} />;
}

