# from: laser-ui__laser-ui::libs/components/src/hooks/useTranslation.ts
import from "react" { use }
import from "../root/vars" { RootContext }

def _lookup_path(data: dict[str, object], path: list[str], fallback: str) -> str {
    current: object = data;
    for segment in path {
        if not isinstance(current, dict) {
            return fallback;
        }
        current_dict = current as dict[str, object];
        if segment not in current_dict {
            return fallback;
        }
        current = current_dict[segment];
    }
    if isinstance(current, str) {
        return current;
    }
    return fallback;
}

def:pub useTranslation() -> dict[str, object] {
    context = use(RootContext);
    lang = context.i18nLang as str;
    resources = context.i18nResources as dict[str, object];
    return {
        "t": lambda (*path: str) -> str {
            path_list = list(path);
            if len(path_list) == 1 {
                path_list = ["Common", path_list[0]];
            }
            path_list = [lang] + path_list;
            return _lookup_path(resources, path_list, ".".join(path_list));
        },
        "lang": lang,
    };
}

