import from "react" { cloneElement, isValidElement }
import from "classnames" { default as classnames }

glob prefixCls = "fam-checkbox-group";

obj:pub CheckBoxGroupProps {
    has className: str | None = None;
    has style: dict[str, object] | None = None;
    has values: list[str | int] | None = None;
    has activeColor: str | None = None;
    has direction: str | None = None;
    has disabled: bool | None = None;
    has maxCheckedCounts: int | None = None;
    has onChange: Callable[[list[str | int]], None] | None = None;
}

def:pub Group(
    className: str | None = None,
    style: dict[str, object] | None = None,
    values: list[str | int] | None = None,
    activeColor: str | None = None,
    direction: str = "horizontal",
    disabled: bool = False,
    onChange: Callable[[list[str | int]], None] | None = None,
    children: list[object] | None = None,
    props: dict[str, object] | None = None,
) -> JsxElement {
    has selectedValues: list[str | int] = [];
    rest = props if props is not None else {};
    can with [values] entry {
        if values is not None {
            selectedValues = values;
        }
    }
    filterChildren: list[object] = [];
    if children and len(children) {
        for item in children {
            if isValidElement(item) {
                filterChildren.append(item);
            }
        }
    }
    def handleCheckBoxChange(value: str | int) {
        newSelectedValues = selectedValues;
        hasValue = -1;
        for (idx, v) in enumerate(newSelectedValues) {
            if v == value {
                hasValue = idx;
                break;
            }
        }
        if hasValue != -1 {
            newSelectedValues = newSelectedValues[:hasValue] + newSelectedValues[hasValue + 1:];
        } else {
            newSelectedValues = newSelectedValues + [value];
        }
        selectedValues = newSelectedValues;
        if onChange {
            onChange(list(newSelectedValues));
        }
    }
    def map_child(child: object) -> object {
        return cloneElement(child, {"onChange": handleCheckBoxChange, "checkedValues": selectedValues, "disabled": disabled, "activeColor": activeColor});
    }
    wrapCls = classnames(prefixCls, className, f"{prefixCls}-{direction}");
    <div className={wrapCls} style={style if style is not None else {}} {**rest}>
        {for item in filterChildren {
            map_child(item);
        }}
    </div>
}

