def:pub BlockIdIndicator(blockId: str, noteTitle: str, className: str = "") -> JsxElement {
    has copied: bool = False;

    async def handle_copy(e: MouseEvent) {
        e.preventDefault();
        e.stopPropagation();
        blockRef = createBlockReference(noteTitle, blockId) as str;
        try {
            await navigator.clipboard.writeText(blockRef);
            copied = True;
            setTimeout(lambda { copied = False; }, 2000);
        } except Exception {
            console.error("Failed to copy block reference");
        }
    }

    <button
        onClick={handle_copy}
        className={"group/block-id inline-flex items-center gap-1 px-1.5 py-0.5 text-xs rounded bg-surface-light/50 hover:bg-surface-light text-text-light-secondary hover:text-text-light-primary border border-border-light/30 transition-all duration-200 " + className}
        title="Click to copy block reference"
        aria-label={f"Copy block reference: {blockId}"}
    >
        <span className="font-mono">#{blockId}</span>
        {if copied {
            <Check className="w-3 h-3 text-accent-green" />
        } else {
            <Copy className="w-3 h-3 opacity-0 group-hover/block-id:opacity-100 transition-opacity" />
        }}
    </button>
}

