def:pub getModifiedArray(current: list[dict[str, object]] | None, target: list[dict[str, object]] | None, keys: list[str] | None = None) -> list[dict[str, object]] {
    if target is None {
        return current if current is not None else [];
    }
    if current is None {
        return target;
    }
    if len(current) != len(target) {
        return target;
    }
    keysToCompare = keys if keys is not None else list(current[0].keys());
    for i in range(len(current)) {
        for key in keysToCompare {
            if current[i][key] != target[i][key] {
                return target;
            }
        }
    }
    return current;
}

def:pub ifModifiedArray(value: list[dict[str, object]], keys: list[str] | None = None) -> Callable[[list[dict[str, object]]], list[dict[str, object]]] {
    return lambda (currentValue: list[dict[str, object]]) -> list[dict[str, object]] { return getModifiedArray(currentValue, value, keys); };
}

def:pub getModifiedObject(current: dict[str, object] | None, target: dict[str, object] | None, keys: list[str] | None = None) -> dict[str, object] {
    if target is None {
        return current if current is not None else {};
    }
    if current is None {
        return target;
    }
    keysToCompare = keys if keys is not None else list(current.keys());
    for key in keysToCompare {
        if current[key] != target[key] {
            return target;
        }
    }
    return current;
}

def:pub ifModifiedObject(value: dict[str, object], keys: list[str] | None = None) -> Callable[[dict[str, object]], dict[str, object]] {
    return lambda (currentValue: dict[str, object]) -> dict[str, object] { return getModifiedObject(currentValue, value, keys); };
}

