import random;

def to_base36(n: int) -> str {
    alphabet = "0123456789abcdefghijklmnopqrstuvwxyz";
    if n == 0 {
        return "0";
    }
    out = "";
    v = n;
    while v > 0 {
        out = alphabet[v % 36] + out;
        v = v // 36;
    }
    return out;
}

def:pub randomId() -> str {
    return to_base36(round(random.random() * (36 ** 8)));
}

