import from "./utils/api.jac" { fetchStoryIds, fetchItemById, StoryType }
import from "./utils/time.jac" { relativeTime }
import from "next/link" { default as Link }
import from "lucide-react" { Triangle, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight }
import from "react" { useEffect }

glob SORT_TABS: list[dict[str, str]] = [{"key": "top", "label": "Top"}, {"key": "new", "label": "New"}, {"key": "show", "label": "Show"}, {"key": "ask", "label": "Ask"}, {"key": "job", "label": "Jobs"}];

def:pub Home() -> JsxElement {
    has stories: list[dict] = [];
    has sortType: str = "top";
    has currentPage: int = 1;
    has totalPages: int = 0;
    has loading: bool = True;
    storiesPerPage = 10;

    def handleNextPage() -> None {
        if currentPage < totalPages {
            currentPage = currentPage + 1;
        }
    }

    def handleFirstPage() -> None {
        currentPage = 1;
    }

    def handleLastPage() -> None {
        currentPage = totalPages;
    }

    def handlePrevPage() -> None {
        if currentPage > 1 {
            currentPage = currentPage - 1;
        }
    }

    def handleSortChange(type: str) -> None {
        if type == sortType {
            return;
        }
        sortType = type;
        currentPage = 1;
    }

    def handleKeyDown(event: KeyboardEvent) -> None {
        if event.key == "ArrowRight" or event.key == "L" {
            handleNextPage();
        } elif event.key == "ArrowLeft" or event.key == "H" {
            handlePrevPage();
        }
    }

    def handleInitialKeyDown(event: KeyboardEvent) -> None {
        if loading {
            return;
        }
        handleKeyDown(event);
    }

    async can with [currentPage, sortType] entry {
        loading = True;
        storyIds = await fetchStoryIds(sortType);
        totalPages = int((len(storyIds) + storiesPerPage - 1) / storiesPerPage);
        paginatedStoryIds = storyIds[(currentPage - 1) * storiesPerPage:currentPage * storiesPerPage];
        storiesData: list[dict] = [];
        for sid in paginatedStoryIds {
            item = await fetchItemById(sid);
            storiesData = storiesData + [item];
        }
        stories = [s for s in storiesData if s and s["title"]];
        loading = False;
    }

    useEffect(lambda {
        window.addEventListener("keydown", handleKeyDown);
        return lambda { window.removeEventListener("keydown", handleKeyDown); };
    }, [currentPage]);

    useEffect(lambda {
        window.addEventListener("keydown", handleInitialKeyDown);
        return lambda { window.removeEventListener("keydown", handleInitialKeyDown); };
    }, [loading]);

    <div className="container mx-auto">
        <div className="flex flex-wrap gap-4 px-4 mb-4 text-sm">
            {for tab in SORT_TABS {
                <button
                    key={tab["key"]}
                    onClick={lambda -> None { handleSortChange(tab["key"]); }}
                    className={"transition hover:text-orange-400 " + ("text-orange-400 underline underline-offset-4" if sortType == tab["key"] else "text-neutral-400")}
                >
                    {tab["label"]}
                </button>
            }}
        </div>
        {if loading {
            <div className="flex justify-center items-center my-4 h-32">
                <p className="text-neutral-400">Loading...</p>
            </div>
        } else {
            <ul className="space-y-2 px-4">
                {for story in stories {
                    <li key={str(story["id"])} className="flex items-center gap-2">
                        <Triangle size={12} className="text-orange-400" />
                        <span className="text-orange-400">{story["score"]}</span>
                        {if story["url"] {
                            <Link href={story["url"] as str} className="hover:underline">{story["title"]}</Link>
                        } else {
                            <Link href={"/story/" + str(story["id"])} className="hover:underline">{story["title"]}</Link>
                        }}
                        <span className="text-neutral-500 text-sm">by {story["by"]}</span>
                        <span className="text-neutral-500 text-sm">{relativeTime(story["time"] as int)}</span>
                    </li>
                }}
            </ul>
            <div className="flex justify-center items-center gap-2 my-4">
                <button onClick={handleFirstPage} className="p-1 hover:text-orange-400"><ChevronsLeft size={18} /></button>
                <button onClick={handlePrevPage} className="p-1 hover:text-orange-400"><ChevronLeft size={18} /></button>
                <span className="text-sm text-neutral-400">{currentPage} / {totalPages}</span>
                <button onClick={handleNextPage} className="p-1 hover:text-orange-400"><ChevronRight size={18} /></button>
                <button onClick={handleLastPage} className="p-1 hover:text-orange-400"><ChevronsRight size={18} /></button>
            </div>
        }}
    </div>
}

