import from "fs" { default as fs }
import json;
import from "@/core/extension/manifest" { getExtensionId }
import type from "@/core/types" { Extension, ExtensionManifest }

glob:pub TEST_DIR = "src/framework/test";

glob:pub TEST_EXTENSIONS_DIR = f"{TEST_DIR}/extensions";

def:pub readTestManifest(`test: str, options: dict[str, object] | None = None) -> dict[str, object] {
    buffer = fs.readFileSync(f"{TEST_EXTENSIONS_DIR}/{`test}/package.json");
    manifest = json.loads(str(buffer)) as dict[str, object];
    mergedOptions = options if options is not None else {};
    return {
        "manifest": {**manifest, **mergedOptions},
        "pathResolver": lambda (path: str) -> str {
            return f"{TEST_EXTENSIONS_DIR}/{`test}/{path}";
        }
    };
}

def:pub newTestManifest(options: dict[str, object] | None = None) -> dict[str, object] {
    mergedOptions = options if options is not None else {};
    return {"name": "foo", "provider": "pippo", "main": "main.js", **mergedOptions};
}

def:pub newTestExtension(source: str | dict[str, object] | None = None) -> Extension {
    manifest: dict[str, object];
    if isinstance(source, str) {
        parts = source.split(".");
        provider = parts[0];
        name = parts[1];
        manifest = newTestManifest({"name": name, "provider": provider});
    } elif source {
        manifest = source as dict[str, object];
    } else {
        manifest = newTestManifest();
    }
    return {
        "id": getExtensionId(manifest as ExtensionManifest),
        "manifest": manifest,
        "status": "inactive",
        "exports": None
    } as Extension;
}

