type Size = Literal["xs", "sm", "md", "lg", "xl", "2xl", "3xl"];
type FormMessageType = Literal["error", "success", "warning", "hint"];

def:pub FormMessage(
    children: object | None = None,
    type: FormMessageType | None = None,
    size: Size = "md",
    className: str | None = None,
    props: dict[str, object] = {},
    ref: Ref[HTMLParagraphElement] = Ref(),
) -> JsxElement | None {
    if not children {
        return None;
    }
    msgType: FormMessageType = type if type else "hint";
    if msgType == "error" {
        return <p
            ref={ref}
            data-slot="message"
            role="alert"
            aria-live="polite"
            className={cn(formMessageVariants(size=size, type=msgType), className)}
            {**props}
        >
            {children}
        </p>;
    }
    return <p
        ref={ref}
        data-slot="message"
        className={cn(formMessageVariants(size=size, type=msgType), className)}
        {**props}
    >
        {children}
    </p>;
}

