async def:pub updateFood(inputs: UpdateFoodInputs) -> Result[None, str] {
    validatedData = createFoodFormSchema.safeParse(inputs);
    if not validatedData.success {
        return Err("Validation failed");
    }
    alteredFood: dict[str, object] = {"name": validatedData.data.name, "quantity": (Number(validatedData.data.quantity) or None), "unit": (validatedData.data.unit or None), "expiry": (validatedData.data.expiry or None), "category": validatedData.data.category};
