import from "react" { createRef, RefObject }

def:pub useRefs(count: int) -> list[RefObject[HTMLElement]] {
    has refs: list[RefObject[HTMLElement]] = [];

    can with entry {
        refs = [createRef() for _ in range(count)];
    }

    can with [count] entry {
        refs = [(refs[i] if i < len(refs) and refs[i] else createRef()) for i in range(count)];
    }

    refs
}

