def:pub checkEnableItem(item: any) -> any {
    return (((item.type == "item") or (item.type == "sub")) and not item.disabled);
}

def:pub getSameLevelEnableItems(arr: list[any]) -> any {
    items: list[any] = [];
    reduceArr = lambda (arr: list[any]) -> any { for item in arr {     if ((item.type == "group") and item.children) {         reduceArr(item.children);     }     elif checkEnableItem(item) {         items.append(item);     } } };
    reduceArr(arr);
    return items;
}

