import ".index.less";

type WaterfallItem = dict[str, str | int];

def:pub App(cols: int = 2, data: list[WaterfallItem] | None = None, style: dict[str, str | int] = {}) -> JsxElement {
    has arrs: list[list[WaterfallItem]] = [];

    def filiter(arr: list[WaterfallItem]) {
        num: int = 0;
        newArr: list[list[WaterfallItem]] = [];
        if len(arrs) == 0 {
            for _ in range(cols) {
                newArr.append([]);
            }
        } else {
            for col in arrs {
                newArr.append(col[:]);
            }
        }
        for element in arr {
            newArr[num].append(element);
            num = (num + 1) % cols;
        }
        arrs = newArr;
    }

    can with [data] entry {
        if data {
            filiter(data);
        }
    }

    <div className="app-1">
        <h1>瀑布流布局</h1>
        <ul className="grid">
            {for item in arrs {
                <li key={JSON.stringify(item)}>
                    {for item1 in item {
                        <div key={str(item1["id"])} className="grid-item">
                            <img src={str(item1["thumbnailUrl"])} alt={str(item1["title"])} />
                        </div>
                    }}
                </li>
            }}
        </ul>
    </div>
}

