# from: facile-it__mutoid::src/utility/hash.ts
def hashString(s: str) -> str {
    h = 0xdeadbeef;
    for i in range(len(s)) {
        h = ((h ^ ord(s[i])) * 2654435761) & 0xFFFFFFFF;
    }
    return str((h ^ (h >> 16)) & 0xFFFFFFFF);
}

