def show_toast_message(toast_type: TypeOptions, message: str) {
    match toast_type {
        case "info":
            toast.info(message);
        case "success":
            toast.success(message);
        case "warning":
            toast.warning(message);
        case "error":
            toast.error(message);
        case "default":
            toast(message);
        case _:
            toast(message);
    }
}

def:pub useToast() -> dict[str, Callable[[TypeOptions, str], None]] {
    return {"showToast": show_toast_message};
}

