import re;
import from "../constants" { MIN_PASSWORD_LENGTH }
import from "./randomUtils" { pickRandomFromArray, shuffleString }

glob Characters: dict[str, str] = {"uppercase": "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "lowercase": "abcdefghijklmnopqrstuvwxyz", "numeric": "1234567890", "special": "!#$%&*+-=?@^_"};

glob similar: str = "iIl1Lo0O";

glob ambiguous: str = "{}[]()/\\'\"`~,;:.<>";

obj PasswordProps {
    has length: int;
    has uppercase: bool = False;
    has lowercase: bool = False;
    has numeric: bool = False;
    has special: bool = False;
    has excludeRepeating: bool = False;
    has excludeSimilar: bool = False;
    has excludeAmbiguous: bool = False;
    has excludeCustom: str = "";
    has custom: bool = False;
    has customSet: str = "";
    has separator: str | None = None;
    has separatorInterval: int | None = None;
}

def isCharacterOptionEnabled(options: PasswordProps, key: str) -> bool {
    if key == "uppercase" { return options.uppercase; }
    if key == "lowercase" { return options.lowercase; }
    if key == "numeric" { return options.numeric; }
    if key == "special" { return options.special; }
    if key == "custom" { return options.custom; }
    return False;
}

def addSeparator(password: str, separator: str, interval: int) -> str {
    chunks: list[str] = [];
    i = 0;
    while i < len(password) {
        chunks.append(password[i:i + interval]);
        i += interval;
    }
    return separator.join(chunks);
}

def:pub generatePassword(options: PasswordProps) -> str {
    validateOptions(options);
    password: str = getRequiredCharacters(options);
    availableCharacters: str = getAvailableCharacters(options);
    while len(password) < options.length {
        character: str = pickRandomFromArray(availableCharacters) as str;
        if options.excludeRepeating and (character in password) {
            continue;
        }
        password += character;
    }
    password = shuffleString(password) as str;
    if options.separator and options.separatorInterval {
        password = addSeparator(password, options.separator, options.separatorInterval);
    }
    return password;
}

def:pub validateOptions(options: PasswordProps) {
    if options.length < MIN_PASSWORD_LENGTH {
        raise ValueError("errors.too_short");
    }
    availableCharacters: str = getAvailableCharacters(options);
    if len(availableCharacters) < 1 {
        raise ValueError("errors.no_characters");
    }
    if options.excludeRepeating and options.length > len(availableCharacters) {
        raise ValueError("errors.too_long");
    }
}

def getAvailableCharacters(options: PasswordProps) -> str {
    availableCharacters: str = "";
    for (key, value) in Characters.items() {
        if isCharacterOptionEnabled(options, key) {
            availableCharacters += value;
        }
    }
    if options.custom and len(options.customSet) > 0 {
        availableCharacters += options.customSet;
    }
    if options.excludeSimilar {
        availableCharacters = re.sub(f"[{similar}]", "", availableCharacters);
    }
    if options.special and not options.excludeAmbiguous {
        availableCharacters += ambiguous;
    }
    if len(options.excludeCustom) > 0 {
        availableCharacters = re.sub(f"[{options.excludeCustom}]", "", availableCharacters);
    }
    return availableCharacters;
}

def getRequiredCharacters(options: PasswordProps) -> str {
    result: str = "";
    characters: dict[str, str] = {**Characters};
    if not options.excludeAmbiguous {
        characters["special"] += ambiguous;
    }
    if options.custom and len(options.customSet) > 0 {
        characters["custom"] = options.customSet;
    }
    for key in characters.keys() {
        if options.excludeSimilar {
            characters[key] = re.sub(f"[{similar}]", "", characters[key]);
        }
        if len(options.excludeCustom) > 0 {
            characters[key] = re.sub(f"[{options.excludeCustom}]", "", characters[key]);
        }
    }
    for (key, value) in characters.items() {
        if isCharacterOptionEnabled(options, key) {
            result += pickRandomFromArray(value) as str;
        }
    }
    return result;
}

