def:pub useLocalAudioToggle() -> list[bool | Callable[[], None]] {
    audio_track: LocalAudioTrack | None = None;

    async def get_local_audio_track() -> LocalAudioTrack | None {
        return None;
    }

    def remove_local_audio_track {
    }

    is_enabled = useIsTrackEnabled(audio_track);
    tracks_data = useTracksSettings();
    save_audio_settings = tracks_data["saveAudioSettings"] as Callable[[bool], None];

    local_participant: object | None = None;

    async def publish_local_audio {
