            track = await get_local_audio_track();
            if track {
                save_audio_settings(True);
                if local_participant {
                    (local_participant as dict)["publishTrack"].call(None, track, {"priority": "low"});
                }
            }
        } except Exception as error {
            console.log(error);
        }
    }

    toggle_audio_enabled = useCallback(lambda {
        if audio_track {
            if local_participant {
                local_track_publication = (local_participant as dict)["unpublishTrack"].call(None, audio_track);
                (local_participant as dict)["emit"].call(None, "trackUnpublished", local_track_publication);
            }
            remove_local_audio_track();
            save_audio_settings(False);
            return;
        }
        publish_local_audio();
    }, [audio_track]);

    return [is_enabled, toggle_audio_enabled];
}

