import from "react" { useEffect }
import from "twilio-video" { LocalTrackPublication, RemoteTrackPublication }

type TrackPublication = LocalTrackPublication | RemoteTrackPublication;
type TrackValue = object | None;

def bind_track_events(
    active_publication: TrackPublication,
    set_track: Callable[[TrackValue], None],
) -> Callable[[], None] {
    def remove_track() {
        set_track(None);
    }
    active_publication.on("subscribed", set_track);
    active_publication.on("unsubscribed", remove_track);
    return lambda {
        active_publication.off("subscribed", set_track);
        active_publication.off("unsubscribed", remove_track);
    };
}

def:pub useTrack(publication: TrackPublication | None) -> TrackValue {
    has track: TrackValue = None;

    useEffect(lambda {
        if publication {
            track = publication.track;
            return bind_track_events(publication, lambda (next_track: TrackValue) { track = next_track; });
        }
        track = None;
    }, [publication]);

    return track;
}

