import from "store/show/types" { SHOW_MORE, IShowState, IShowMoreAction, SWITCH_KANBAN, ISwitchKanbanAction }

type ShowActions = IShowMoreAction | ISwitchKanbanAction;

glob initialState: IShowState = {"list": {"backlog": True, "progress": True, "complete": True}, "kanban": True};

def:pub show(
    state: IShowState = initialState,
    action: ShowActions
) -> IShowState {
    switch action["type"] {
        case SHOW_MORE:
            return {**state, "list": {**action["payload"] as dict[str, bool]}};
            break;
        case SWITCH_KANBAN:
            return {**state, "kanban": action["payload"] as bool};
            break;
        default:
            return state;
            break;
    }
}

