import from "classnames" { default as classNames }
import from "react" { useEffect }
import from "./script/util.jac" { formatDate }

glob sizeClass = {"large": "text-lg", "middle": "text-base", "small": "text-sm"};

glob RESET_TIME = (((-1000 * 60) * 60) * 8);

glob REFRESH_INTERVAL = 1000;

obj CountDownProps {
    has size: str = "middle";
    has time: int | None = None;
    has format: str | None = None;
    has onFinish: Callable[[], None] | None = None;
}

def:pub CountDown(
    size: str = "middle",
    time: int | None = None,
    format: str | None = None,
    onFinish: Callable[[], None] | None = None,
) -> JsxElement {
    has now: int = time if time is not None else 0;
    has countdown: float | None = None;

    def stopTimer() -> None {
        if countdown {
            clearInterval(countdown);
            countdown = None;
        }
    }

    useEffect(lambda {
        if now >= 0 {
            countdown = setInterval(lambda {
                if now <= 0 {
                    if onFinish {
                        onFinish();
                    }
                    stopTimer();
                } else {
                    now = now - 1;
                }
            }, REFRESH_INTERVAL);
        }
        return lambda {
            stopTimer();
        };
    }, [now]);

    <span className={classNames(sizeClass[size])}>
        {formatDate(Date(RESET_TIME + now * 1000), format if format else "HH:mm:ss")}
    </span>
}

