import from "@/components/ui" {
    Button,
    DialogBody,
    DialogClose,
    DialogContent,
    DialogFooter,
    DialogHeader,
    DialogTitle,
}
import from "@/features/groups/lib/actions" { removeGroup }

def:pub DeleteGroupDialogContent(
    groupId: str,
    onDialogClose: Callable[[], None],
    onParentClose: Callable[[], None] | None = None,
    navigateOnSuccess: Callable[[], None] | None = None,
) -> JsxElement {
    has isLoading: bool = False;

    def handleCancel(e: MouseEvent) {
        if onParentClose {
            onParentClose();
        }
    }

    async def handleDelete(e: MouseEvent) {
        if isLoading {
            return;
        }
        isLoading = True;
        result = await removeGroup(groupId);
        if not result.ok {
            alert("Something went wrong. Please try again.");
            onDialogClose();
            if onParentClose {
                onParentClose();
            }
            isLoading = False;
        } else {
            alert("Successfully deleted");
            onDialogClose();
            if onParentClose {
                onParentClose();
            }
            isLoading = False;
            if navigateOnSuccess {
                navigateOnSuccess();
            }
        }
    }

    <DialogContent>
        <DialogHeader>
            <DialogTitle>Delete Group</DialogTitle>
        </DialogHeader>
        <DialogBody>
            <p>Are you sure you want to delete this group?</p>
        </DialogBody>
        <DialogFooter>
            <DialogClose asChild>
                <Button variant="cancel" size="sm" onClick={handleCancel}>
                    Cancel
                </Button>
            </DialogClose>
            <Button variant="danger" size="sm" onClick={handleDelete} disabled={isLoading}>
                Delete
            </Button>
        </DialogFooter>
    </DialogContent>
}

