# from: frau-azadeh__resume-app::components/PasswordStrengthMeter.tsx
import re;
import from "clsx" { clsx }

def:pub PasswordStrengthMeter(password: str) -> JsxElement {
    if not password {
        return <></>;
    }

    hasUpper = bool(re.search(r"[A-Z]", password));
    hasLower = bool(re.search(r"[a-z]", password));
    hasNumber = bool(re.search(r"[0-9]", password));
    hasSymbol = bool(re.search(r"[@$!%*?&]", password));
    score = len([flag for flag in [hasUpper, hasLower, hasNumber, hasSymbol] if flag]);
    color = "";
    percent = 0;

    if score <= 1 {
        color = "bg-red-500";
        percent = 25;
    } elif score == 2 {
        color = "bg-yellow-500";
        percent = 50;
    } elif score == 3 {
        color = "bg-blue-500";
        percent = 75;
    } else {
        color = "bg-green-600";
        percent = 100;
    }

    <div className="space-y-1">
        <div className="h-2 w-full bg-gray-200 rounded-full owerflow-hidden">
            <div
                className={clsx("h-full transition-all duration-300", color)}
                style={{"width": f"{percent}%"}}
            />
        </div>
    </div>
}

