def:pub pickBy[V](object: dict[str, V], predicate: Callable[[V, str], bool]) -> dict[str, V] {
    acc: dict[str, V] = {};
    for key in object.keys() {
        if predicate(object[key], key) {
            acc[key] = object[key];
        }
    }
    return acc;
}

