import from .Cancel { Cancel }

type CancelListener = Callable[[Cancel], None];
type Canceler = Callable[[str], None];
type CancelExecutor = Callable[[Canceler], None];

obj CancelToken {
    has reason: Cancel | None = None;
    has _listeners: list[CancelListener] | None = None;
    has promise: dict[str, object] | None = None;

    def init(executor: CancelExecutor) {
        if not callable(executor) {
            raise TypeError("executor must be a function.");
        }
        token = self;

        def onCancel(cancel: Cancel) -> None {
            if not token._listeners {
                return;
            }
            for listener in token._listeners {
                listener(cancel);
            }
            token._listeners = None;
        }

        def cancel(message: str = "") -> None {
            if token.reason {
                return;
            }
            token.reason = Cancel(message=message);
            onCancel(token.reason);
        }

        def then(onfulfilled: Callable[[Cancel], object]) -> object {
            if token.reason {
                return onfulfilled(token.reason);
            }
            token.subscribe(lambda (c: Cancel) { onfulfilled(c); });
            return None;
        }

        self.promise = {"then": then};
        executor(cancel);
    }

    def throwIfRequested {
        if self.reason {
            raise self.reason;
        }
    }

    def subscribe(listener: CancelListener) {
        if self.reason {
            listener(self.reason);
            return;
        }
        if self._listeners {
            self._listeners.append(listener);
        } else {
            self._listeners = [listener];
        }
    }

    def unsubscribe(listener: CancelListener) {
        if not self._listeners {
            return;
        }
        index = self._listeners.index(listener);
        if index != -1 {
            del self._listeners[index];
        }
    }

    static def source -> dict[str, object] {
        canceler: Canceler | None = None;
        token = CancelToken(lambda (c: Canceler) { canceler = c; });
        return {"token": token, "cancel": canceler};
    }
}

glob:pub default = CancelToken;

