        {"★" * level}
        {"☆" * (5 - level)}
    </span>
}

def:pub SkillForm(
    onAdd: Callable[[SkillFormData], None],
    skills: list[SkillFormData],
    onDelete: Callable[[int], None],
) -> JsxElement {
    has skill_name: str = "";
    has skill_level: str = "1";
    has name_error: str | None = None;

    selected_level = int(skill_level) if skill_level else 1;

    def handle_submit(e: FormEvent) {
        e.preventDefault();
        trimmed = skill_name.strip();
        if not trimmed {
            name_error = "نام مهارت الزامی است";
            return;
        }
        name_error = None;
        onAdd(SkillFormData(skill_name=trimmed, skill_level=int(skill_level)));
        skill_name = "";
        skill_level = "1";
    }

    <div
        dir="rtl"
        className="mx-auto bg-white p-6 rounded-lg shadow-md border-t border-gray-200 pt-6 mb-10 space-y-8"
    >
        <h3 className="font-semibold mb-4 text-gray-800 text-right">
            مهارت‌های تخصصی
        </h3>
        <form
            onSubmit={handle_submit}
            className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6"
        >
            <div className="md:col-span-2">
                <Input
                    value={skill_name}
                    onChange={lambda (e: ChangeEvent) { skill_name = e.target.value; }}
                    placeholder="نام مهارت فنی"
                    error={name_error}
                    className="w-full border border-gray-300 rounded-md px-4 py-2 text-gray-700 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-yellow-400 focus:border-yellow-400 transition"
                />
            </div>
            <div className="md:col-span-2">
                <label className="block text-sm font-semibold mb-2 text-gray-700">
                    سطح مهارت:
                </label>
                <div className="flex items-center gap-4 justify-end">
                    {for star in [1, 2, 3, 4, 5] {
                        <label key={str(star)} className="cursor-pointer select-none text-3xl">
                            <input
                                type="radio"
                                value={str(star)}
                                checked={skill_level == str(star)}
                                onChange={lambda (e: ChangeEvent) { skill_level = e.target.value; }}
                                className="hidden"
                            />
                            <span
                                className={"text-yellow-400" if selected_level >= star else "text-gray-300"}
                                aria-label={f"{star} ستاره"}
                            >
                                ★
                            </span>
                        </label>
                    }}
                </div>
            </div>
            <div className="md:col-span-2">
                <Button type="submit" variant="success" size="md">
                    افزودن مهارت فنی
                </Button>
            </div>
        </form>
        <SkillList
            title="مهارت‌های فنی"
            items={[SkillListItem(label=s.skill_name, description=render_stars(s.skill_level)) for s in skills]}
            onDelete={onDelete}
        />
    </div>
}

