import from react { useEffect, useRef }

def:pub useAutoFocus(shouldFocus: bool) -> Ref[HTMLElement] {
    ref = useRef(None);
    useEffect(lambda -> None {
        if shouldFocus and ref.current {
            ref.current.focus();
        }
    }, [ref, shouldFocus]);
    return ref;
}

