import from "@ninna-ui/utils" { cn }

def buttonVariants(
    variant: str | None = None,
    color: str | None = None,
    size: str | None = None,
    radius: str | None = None,
    fullWidth: bool = False,
) -> str {
    v = variant if variant is not None else "solid";
    c = color if color is not None else "primary";
    s = size if size is not None else "md";
    r = radius if radius is not None else "md";
    base = cn("inline-flex items-center justify-center", f"btn-{v}", f"btn-{c}", f"btn-{s}", f"btn-{r}");
    if fullWidth {
        return cn(base, "w-full");
    }
    return base;
}

glob BUTTON_SPINNER_SIZES: dict[str, str] = {
    "sm": "h-3 w-3",
    "md": "h-4 w-4",
    "lg": "h-5 w-5",
};

def:pub Button(
    variant: str | None = None,
    color: str | None = None,
    size: str | None = None,
    radius: str | None = None,
    loading: bool = False,
    fullWidth: bool = False,
    leftIcon: object | None = None,
    rightIcon: object | None = None,
    disabled: bool = False,
    className: str | None = None,
    children: object | None = None,
    ref: Ref[HTMLButtonElement] = Ref(),
    props: dict[str, object] = {},
) -> JsxElement {
    isDisabled = disabled or loading;
    sizeVal = size if size is not None else "md";
    <button
        ref={ref}
        data-slot="button"
        className={cn(buttonVariants(variant=variant, color=color, size=sizeVal, radius=radius, fullWidth=fullWidth), className)}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        data-loading={loading}
        {**props}
    >
        {leftIcon and <span data-slot="icon">{leftIcon}</span>}
        {loading and <span className={cn("animate-spin rounded-full border-2 border-current border-t-transparent", BUTTON_SPINNER_SIZES.get(sizeVal, ""))} aria-hidden="true" />}
        {children}
        {rightIcon and <span data-slot="icon">{rightIcon}</span>}
    </button>
}

