# language: jac
# from: deivuss331__react-headless-timeline::lib/hooks/useOffsetCalculator.ts
import from "date-fns" { differenceInMilliseconds }
import from "lib/components/TimelineProvider" { useTimelineContext }

def:pub useOffsetCalculator -> Callable[[object], str] {
    timeline = useTimelineContext();

    def calc(startDate: object) -> str {
        timelineDatesDiff = Math.abs(differenceInMilliseconds(timeline.endDate, timeline.startDate));
        startDatesDiff = Math.abs(differenceInMilliseconds(startDate, timeline.startDate));
        offsetPercentage = ((startDatesDiff * 100) / timelineDatesDiff);
        return f"{offsetPercentage}%";
    }

    return calc;
}

# Jac lang
# from: ninetailed-inc__experience.js::sdks/javascript/src/lib/experience/decodeExperienceVariantsMap.ts
def:pub decodeExperienceVariantsMap(encodedExperienceVariantsMap: str) -> dict[str, int] {
    experientVariantsAssignments = encodedExperienceVariantsMap.split(",");
    experienceVariantsMap: dict[str, int] = {};
    for experienceVariantAssignment in experientVariantsAssignments {
        parts = experienceVariantAssignment.split("=");
        experienceId = parts[0];
        variantIndexString = parts[1] if len(parts) > 1 else "";
        variantIndex = int(variantIndexString);
        if not experienceId or not variantIndex {
            continue;
        }
        experienceVariantsMap[experienceId] = variantIndex;
    }
    return experienceVariantsMap;
}

