# from: Hasuro-R__react-slide-craft::utils/getPaddings.ts
def:pub getPaddings(padding: str) -> tuple[str, str, str, str] {
    paddingValues = [value.strip() for value in padding.split(" ")];
    paddingTop = paddingValues[0] or "0";
    paddingRight = paddingValues[1] or paddingTop;
    paddingBottom = paddingValues[2] or paddingTop;
    paddingLeft = paddingValues[3] or paddingRight;
    return (paddingTop, paddingRight, paddingBottom, paddingLeft);
}

