async def:pub verifyAISettings(apiKey: str) -> VerifyAISettingsResult {
    try {
        client = OpenAI(api_key=apiKey);
        completion = await client.chat.completions.create(
            max_completion_tokens=5,
            messages=[{"content": "hi", "role": "user"}],
            model="gpt-4o-mini"
        );
        choices = completion.choices;
        if (
            len(choices) == 0
            or choices[0].message is None
            or choices[0].message.content is None
        ) {
            raise ValueError("No response from API");
        }
        return VerifyAISettingsResult(success=True, error=None);
    } except Exception as e {
        return VerifyAISettingsResult(
            success=False,
            error=getAISettingsErrorMessage(e)
        );
    }
}

