import from "react" { Children, isValidElement, cloneElement }
import from "classnames" { default as classnames }

glob prefixCls = "fam-radio-group";

obj:pub RadioGroupProps {
    has className: str | None = None;
    has style: dict[str, object] | None = None;
    has value: str | int | None = None;
    has activeColor: str | None = None;
    has direction: str | None = None;
    has disabled: bool | None = None;
    has onChange: Callable[[str | int], None] | None = None;
}

def:pub Group(
    className: str | None = None,
    style: dict[str, object] | None = None,
    value: str | int | None = None,
    activeColor: str | None = None,
    direction: str = "horizontal",
    disabled: bool = False,
    onChange: Callable[[str | int], None] | None = None,
    children: object | None = None,
) -> JsxElement {
    has selectedValue: str | int | None = None;
    can with [value] entry {
        if value {
            selectedValue = value;
        }
    }
    def handleRadioChange(v: str | int) {
        selectedValue = v;
        if onChange {
            onChange(v);
        }
    }
    def mapChild(child: object) -> object {
        if not isValidElement(child) {
            return child;
        }
        childProps = (child as dict[str, object])["props"] as dict[str, object];
        itemCls = childProps["className"] as str if "className" in childProps else "";
        itemDisabled = True if disabled else (childProps["disabled"] as bool if "disabled" in childProps else False);
        merged = {**childProps, "className": itemCls, "selectedValue": selectedValue, "activeColor": activeColor, "disabled": itemDisabled, "onChange": handleRadioChange};
        return cloneElement(child, merged);
    }
    groupCls = classnames(prefixCls, className, {f"{prefixCls}-horizontal": direction == "horizontal", f"{prefixCls}-vertical": direction == "vertical"});
    newChildren = Children.map(children, mapChild);
    <div className={groupCls} style={style if style is not None else {}}>{newChildren}</div>
}

