# from: cool-hooks__react-wordpress-hooks::utils/passToBody.ts
def _append_value(value: str | int | bool) -> str {
    if isinstance(value, bool) {
        return "true" if value else "false";
    }
    return str(value);
}

def passToBody(options: dict[str, str | int | bool]) -> dict[str, str] {
    urlencoded: dict[str, str] = {};
    for (key, value) in options.items() {
        urlencoded[key] = _append_value(value);
    }
    return urlencoded;
}

