import type from "@/core/types" { Extension }
import from "@/util/log" { Logger }
import from "@/core/extension-context/get" { getExtensionContext }
import from "@/core/extension/set" { setExtensionStatus }

glob LOG = Logger.getLogger("extendit/core");

async def:pub deactivateExtension(extensionId: str) -> Extension {
    ctx = getExtensionContext(extensionId, True);
    extension = ctx.extension;
    if extension.status != "active" {
        return extension;
    }
    try {
        module = ctx.module;
        deactivateFn = module?.deactivate if module else None;
        if deactivateFn and callable(deactivateFn) {
            extension = setExtensionStatus(extensionId, "deactivating");
            await deactivateFn(ctx);
        }
        extension = setExtensionStatus(extensionId, "inactive");
    } except Exception as error {
        LOG.error(
            f"An error occurred during deactivation of extension '{extensionId}':",
            error
        );
        extension = setExtensionStatus(extensionId, "rejected", error);
    }
    return extension;
}

