def:pub useFileAdapter(metadata: FileIdRef) -> dict[str, object] {
    dispatch = useDispatch() as AppDispatch;
    directoryState = useReduxDirectoryState(dispatch) as DirectoryState;
    localDirectoryDatabase = useLocalDirectoryDatabase(databaseId);
    downloader = useDownloadManager();
    fileMetadata = useSelector(selectFileMetadata(metadata));
    fileContent = useSelector(selectFileContent(metadata));
    fileStatus = useSelector(selectFileStatus(metadata));
    fetchFileMetadata = useMemo(
        lambda () -> Callable[[], None] {
            return lambda () -> None {
                File.fetchFileMetadata(metadata, localDirectoryDatabase, directoryState);
            };
        },
        [metadata.id]
    );
    fetchFileContent = useMemo(
        lambda () -> Callable[[], None] {
            return lambda () -> None {
                File.fetchFileContent(metadata, localDirectoryDatabase, directoryState);
            };
        },
        [metadata.id]
    );
    fetchFile = useMemo(
        lambda () -> Callable[[], None] {
            return lambda () -> None {
                File.fetchFile(metadata, localDirectoryDatabase, directoryState);
            };
        },
        [metadata.id]
    );
    deleteFile = useMemo(
        lambda () -> Callable[[], None] {
            return lambda () -> None {
                File.deleteFile(metadata, localDirectoryDatabase, directoryState);
            };
        },
        [metadata.id]
    );
    updateContent = useMemo(
        lambda () -> Callable[[str], None] {
            return lambda (newContent: str) -> None {
                File.saveFile(
                    {**fileMetadata, "content": newContent},
                    localDirectoryDatabase,
                    directoryState
                );
            };
        },
        [metadata.id]
    );
    renameFile = useMemo(
        lambda () -> Callable[[str], None] {
            return lambda (newName: str) -> None {
                File.saveFileMetadata(
                    {**fileMetadata, "name": newName},
                    localDirectoryDatabase,
                    directoryState
                );
            };
        },
        [metadata.id]
    );
    downloadFile = useMemo(
        lambda () -> Callable[[], None] {
            return lambda () -> None {
                File.downloadFile(metadata, localDirectoryDatabase, directoryState, downloader);
            };
        },
        [metadata.id]
    );
    return {
        "fileMetadata": fileMetadata,
        "fileContent": fileContent,
        "fileStatus": fileStatus,
        "fetchFileMetadata": fetchFileMetadata,
        "fetchFileContent": fetchFileContent,
        "fetchFile": fetchFile,
