def:pub useMountedState() -> Callable[[], bool] {
    mountedRef = useRef(False);
    getMounted = useCallback(lambda -> bool { return mountedRef.current; }, []);
    useEffect(lambda {
        mountedRef.current = True;
        return lambda { mountedRef.current = False; };
    });
    return getMounted;
}

def:pub useDeepMemo[T](value: T) -> T {
    ref = useRef(value);
    if not isEqual(ref.current, value) {
        ref.current = value;
    }
    return ref.current;
}

def:pub useRefFn[T: Callable[..., object]](fn: T) -> {"current": T} {
    refFn = useRef(fn);
    useEffect(lambda { refFn.current = fn; }, [fn]);
    return refFn;
}

