def attach_audio_track(track: TwilioAudioTrack, element: HTMLAudioElement | None) {
    if element {
        track.attach(element);
    }
}

def detach_audio_track(track: TwilioAudioTrack, element: HTMLAudioElement | None) {
    if element {
        track.detach(element);
    }
}

def run_audio_effect(track: TwilioAudioTrack, audio_ref: Ref[HTMLAudioElement]) -> Callable[[], None] {
