def iconButtonVariants(
    variant: str | None = None,
    color: str | None = None,
    size: str | None = None,
    radius: str | None = None,
) -> str {
    v = variant if variant is not None else "solid";
    c = color if color is not None else "primary";
    s = size if size is not None else "md";
    r = radius if radius is not None else "md";
    return cn("inline-flex items-center justify-center", f"icon-btn-{v}", f"icon-btn-{c}", f"icon-btn-{s}", f"icon-btn-radius-{r}");
}

def IconButtonIcon(icon: object | None, size: str, loading: bool) -> JsxElement {
    if loading {
        return <span
            className={cn("animate-spin rounded-full border-2 border-current border-t-transparent", ICON_BUTTON_SPINNER_SIZES.get(size, ""))}
            aria-hidden="true"
        />;
    }
    return <span data-slot="icon" className={cn("inline-flex items-center justify-center", ICON_SIZES.get(size, ""))} aria-hidden="true">{icon}</span>;
}

def:pub IconButton(
    icon: object | None = None,
    variant: str = "solid",
    color: str = "primary",
    size: str = "md",
