    loading: bool = False,
    disabled: bool = False,
    className: str | None = None,
    ariaLabel: str | None = None,
    ref: Ref[HTMLButtonElement] = Ref(),
    props: dict[str, object] = {},
) -> JsxElement {
    isDisabled = disabled or loading;
    <button
        ref={ref}
        data-slot="icon-button"
        type="button"
        className={cn(iconButtonVariants(variant=variant, color=color, size=size, radius=radius), className)}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        aria-label={ariaLabel}
        data-loading={loading}
        {**props}
    >
        <IconButtonIcon icon={icon} size={size} loading={loading} />
    </button>
}

