import from "react" { useEffect }

def:pub CurrentTimeIndicator(hourHeight: float) -> JsxElement {
    has position: float = 0.0;

    useEffect(lambda {
        def update_position() {
            now = new(Date);
            hours = now.getHours();
            minutes = now.getMinutes();
            total_minutes = hours * 60 + minutes;
            position = (total_minutes / 60.0) * hourHeight;
        }
        update_position();
        interval = setInterval(lambda { update_position(); }, 60000);
        return lambda { clearInterval(interval); };
    }, [hourHeight]);

    <div
        className="pointer-events-none absolute inset-x-0 z-40 flex items-center"
        style={{"top": f"{position}px"}}
    >
        <div className="size-3 -translate-x-1/2 rounded-full bg-red-500 shadow-md" />
        <div className="h-0.5 flex-1 bg-red-500 shadow-sm" />
    </div>
}

# Jac lang
# from: dawangcoding__ClawUI::shared/assistant-identity.ts
import from "./types/gateway-rpc" { RPC }

glob MAX_ASSISTANT_NAME: int = 50;

glob MAX_ASSISTANT_AVATAR: int = 200;

glob:pub DEFAULT_ASSISTANT_NAME: str = "Assistant";

glob:pub DEFAULT_ASSISTANT_AVATAR: str = "A";

obj:pub AssistantIdentity {
    has name: str;
    has avatar: str | None;
    has agentId: str | None = None;
}

obj:pub LoadAssistantIdentityOptions {
    has connected: bool;
    has sessionKey: str;
    has rpc: Callable[[str, dict[str, str]], Awaitable[dict[str, object] | None]];
}

def coerceIdentityValue(value: str | None, maxLength: int) -> str | None {
    if not isinstance(value, str) {
        return None;
    }
    trimmed = value.strip();
    if not trimmed {
        return None;
    }
    return trimmed if len(trimmed) <= maxLength else trimmed[0:maxLength];
}

def:pub normalizeAssistantIdentity(input: dict[str, object] | None = None) -> AssistantIdentity {
    name_input: str | None = None;
    avatar_input: str | None = None;
    if input is not None {
        raw_name = input?["name"];
        if isinstance(raw_name, str) {
            name_input = raw_name;
        }
        raw_avatar = input?["avatar"];
        if isinstance(raw_avatar, str) {
            avatar_input = raw_avatar;
        }
    }
    coerced_name = coerceIdentityValue(name_input, MAX_ASSISTANT_NAME);
    name = coerced_name if coerced_name is not None else DEFAULT_ASSISTANT_NAME;
    coerced_avatar = coerceIdentityValue(avatar_input, MAX_ASSISTANT_AVATAR);
    agent_id: str | None = None;
    if input is not None {
        raw_agent = input?["agentId"];
        if isinstance(raw_agent, str) and raw_agent.strip() {
            agent_id = raw_agent.strip();
        }
    }
    return AssistantIdentity(agentId=agent_id, name=name, avatar=coerced_avatar);
}

async def:pub loadAssistantIdentity(opts: LoadAssistantIdentityOptions) -> AssistantIdentity | None {
    if not opts.connected {
        return None;
    }
    session_key = opts.sessionKey.strip();
    params: dict[str, str] = {};
    if session_key {
        params = {"sessionKey": session_key};
    }
    try {
        res = await opts.rpc(RPC.AGENTS_IDENTITY, params);
        if not res {
            return None;
        }
        return normalizeAssistantIdentity(res as dict[str, object]);
    } except Exception {
        return None;
    }
}

