import from react { useEffect }

obj HTMLElement {
    def contains(target: object) -> bool;
}

obj DOMRef {
    has current: HTMLElement | None = None;
}

obj MouseEvent {
    has target: object;
}

def:pub useOutsideClick(ref: DOMRef, callback: callable | None = None) -> None {
    useEffect(lambda () -> object | None {
        if callback {
            handleClickOutside = lambda (event: MouseEvent) -> None {
                if ref.current and not ref.current.contains(event.target) {
                    callback();
                }
            };
            document.addEventListener("mousedown", handleClickOutside);
            return lambda () -> None {
                document.removeEventListener("mousedown", handleClickOutside);
            };
        }
        return None;
    }, [ref, callback]);
}

