import from "react" { useEffect, useState }
import from "./use-daily-limit" { DAY_MS }

def currentUtcDay() -> int {
    now = Date.now() as float;
    dayMs = DAY_MS as float;
    return int(Math.floor(now / dayMs));
}

def scheduleUtcDayRollover(utcDay: int, setUtcDay: object) -> object {
    now = Date.now() as float;
    dayMs = DAY_MS as float;
    msUntilRollover = int((utcDay + 1) * dayMs - now);
    timer = window.setTimeout(
        lambda { setUtcDay(currentUtcDay); },
        max(1000.0, float(msUntilRollover)),
    );
    return lambda { window.clearTimeout(timer); };
}

def:pub useProfile(enabled: bool = True) -> int {
    (utcDay, setUtcDay) = useState(0);
    useEffect(lambda { setUtcDay(currentUtcDay()); }, []);
    useEffect(
        lambda { return scheduleUtcDayRollover(utcDay as int, setUtcDay); },
        [utcDay],
    );
    if not enabled {
        return 0;
    }
    return utcDay as int;
}

