obj FieldData {
    has name: str;
    has display_value: str;
}

def:pub ReadonlyInput(fieldData: FieldData, editObj: dict[str, str] | None = None) -> JsxElement | None {
    name = fieldData.name;
    defaultValue = "";
    if editObj is not None and name in editObj and editObj[name] {
        defaultValue = editObj[name];
    }
    if not defaultValue {
        return None;
    }
    return (
        <div
            style={{
                "display": "flex",
                "alignItems": "left",
                "justifyContent": "left",
                "flexDirection": "column",
                "textAlign": "left",
                "marginBottom": "15px"
            }}
        >
            <label htmlFor={fieldData.name} className="labelTitle">
                {f"{fieldData.display_value}:"}
            </label>
            <label
                style={{
                    "marginBottom": "10px",
                    "backgroundColor": "var(--primary-light)",
                    "cursor": "not-allowed",
                    "borderColor": "0.134rem var(--primary-dark)",
                    "borderRadius": "var(--border-radius-container)",
                    "padding": "15px 15px",
                    "fontSize": "var(--button-font-size)",
                    "pointerEvents": "none",
                    "opacity": "0.4"
                }}
                htmlFor={fieldData.name}
            >
                {defaultValue}
            </label>
        </div>
    );
}

