import re;
import unicodedata;

def normalize(text: str) -> str {
    return re.sub(r"[\u0300-\u036f]", "", unicodedata.normalize("NFD", text)).lower();
}

def:pub matchesQuery(candidate: str, query: str) -> bool {
    q = normalize(query.strip());
    if not q {
        return True;
    }
    return q in normalize(candidate);
}

