# Jac lang
# from: bitcraft3r__0xVenture-Capitalist::api/player/upgrade/buy/[userId]/route.ts
async def:pub GET(
    user_id: str,
    upgrade_id: str | None = None,
    price: float | None = None,
    business_name: str | None = None,
    upgrade_description: str | None = None,
) -> dict[str, str] {
    userId = user_id;
    upgradeId = upgrade_id;
    priceVal = price if price is not None else 0.0;
    businessName = business_name;
    upgradeDescription = upgrade_description if upgrade_description is not None else "";
    purchased = False;
    if purchased {
        return {"error": "Already purchased upgrade"};
    }
    userCoins = 0.0;
    if userCoins < priceVal {
        return {"error": "Not enough coins"};
    }
    try {
        player = {"id": userId};
        if not player {
            return {"error": "Error deducting coins."};
        }
        upgrade = {"id": upgradeId if upgradeId is not None else "", "purchased": True};
        if not upgrade {
            return {"error": "Error updating upgrade.purchased to true."};
        }
        if businessName == "All Businesses" {
            business = {"scope": "all", "userId": userId};
            if business and player and upgrade {
                return {"success": f"{upgradeDescription} upgrade purchased!"};
            }
        } else {
            business = {"scope": businessName if businessName is not None else "", "userId": userId};
            if business and player and upgrade {
                return {"success": f"{upgradeDescription} upgrade purchased!"};
            }
        }
    } except Exception {
        return {"error": "Something went wrong"};
    }
    return {};
}

