# from: dokasto__Saidia::main/files/parse-md.ts
import re;
import from main.files.clean { splitText }
import from main.files.parse_html { Section }

async def readFileUtf8(filePath: str) -> str {
    with open(filePath, "r", encoding="utf-8") as f {
        return f.read();
    }
}

obj ParseMdInput {
    has filePath: str | None = None;
    has markdownText: str | None = None;
}

async def parseMd(input: ParseMdInput) -> list[Section] {
    markdown: str | None = None;
    if input.filePath {
        markdown = await readFileUtf8(input.filePath);
    } else {
        markdown = input.markdownText;
    }

    if markdown is None {
        return [];
    }

    sections: list[Section] = [];
    lines = markdown.split("\n");
    header: str | None = None;
    text = "";

    for line in lines {
        isHeader = re.match(r"^#+\s", line);
        if isHeader {
            if header is not None {
                if text == "" {
                    continue;
                }
                sections.append(Section(section=header, content=splitText(text)));
            }
            header = line.replace("#", "").strip();
            text = "";
        } else {
            text += line + "\n";
        }
    }

    finalHeader = header if header is not None else "";
    sections.append(Section(section=finalHeader, content=splitText(text)));
    return sections;
}

