obj TextNode {
    has nodeType: int;
    has nodeValue: str | None = None;
    has textContent: str | None = None;
}

glob TEXT_NODE: int = 3;
glob ELEMENT_NODE: int = 1;

import from .text_nodes { textNodes, WalkerLike }

def getUniqueCharsInPage(nodes: WalkerLike | list[object]) -> set[str] {
    chars: set[str] = set();
    for raw in textNodes(nodes) {
        item: TextNode = raw as TextNode;
        if item.nodeType == TEXT_NODE and item.nodeValue {
            for char in item.nodeValue {
                chars.add(char);
            }
        } elif item.nodeType == ELEMENT_NODE and item.textContent {
            for char in item.textContent {
                chars.add(char);
            }
        }
    }
    return chars;
}

