import from "./dictionary.json" { default as dictionary }
import from "./randomUtils" { getBooleanSequence, getRandomInt }

obj DictEntry {
    has word: str;
}

obj PassphraseProps {
    has wordCount: int;
    has swapCharacters: bool;
    has randomizeCase: bool;
    has allowRepeating: bool;
    has separator: str;
}

def:pub generatePassphrase(options: PassphraseProps) -> str {
    entries: list[DictEntry] = dictionary as list[DictEntry];
    words: list[str] = [];
    i: int = 0;
    while i < options.wordCount {
        entry: DictEntry = entries[getRandomInt(0, len(entries))] as DictEntry;
        word: str = entry.word;
        if not options.allowRepeating and word in words {
            {};
        } else {
            words.append(word);
            i += 1;
        }
    }
    result: str = options.separator.join(words).lower();
    print(result);
    if options.swapCharacters {
        result = swapCharacters(result);
    }
    if options.randomizeCase {
        result = RandomUpperCase(result);
    }
    return result;
}

def RandomUpperCase(passphrase: str) -> str {
    sequence: list[bool] = getBooleanSequence(len(passphrase)) as list[bool];
    result: str = "";
    for idx = 0 while idx < len(passphrase) with idx += 1 {
        result += passphrase[idx].upper() if sequence[idx] else passphrase[idx];
    }
    return result;
}

def swapCharacters(passphrase: str) -> str {
    sequence: list[bool] = getBooleanSequence(len(passphrase)) as list[bool];
    result: str = "";
    for idx = 0 while idx < len(passphrase) with idx += 1 {
        if sequence[idx] {
            ch: str = passphrase[idx].lower();
            switch ch {
                case "a":
                    result += "@" if getRandomInt(0, 100) < 50 else "4";
                    break;
                case "e":
                    result += "3";
                    break;
                case "i":
                    result += "!";
                    break;
                case "s":
                    result += "$" if getRandomInt(0, 100) < 50 else "5";
                    break;
                default:
                    result += passphrase[idx];
                    break;
            }
        } else {
            result += passphrase[idx];
        }
    }
    return result;
}

