def isError(error: object) -> bool {
    return error is not None and hasattr(error, "message");
}

def getStacktrace(error: object) -> list[str] {
    stacktrace = getattr(error, "stacktrace", None);
    opera_src = getattr(error, "opera#sourceloc", None);
    if stacktrace is not None or opera_src is not None {
        st = stacktrace if stacktrace is not None else "";
        return [line for line in str(st).split("\n") if line != ""];
    }
    stack = getattr(error, "stack", None);
    if stack is not None {
        return [line for line in str(stack).split("\n") if line != ""];
    }
    return ["No stacktrace available"];
}

