import from "react" { useEffect, useRef }
import from "classnames" { default as classnames }

def:pub Modal(
    children: object | None = None,
    maxWidth: str = "lg",
    onClickOutside: Callable[[], None] | None = None
) -> JsxElement {
    contentEl = useRef(None);

    useEffect(lambda {
        def listener(e: MouseEvent) {
            el = contentEl.current;
            if el and not el.contains(e.target) {
                if onClickOutside {
                    onClickOutside();
                }
            }
        }
        document.addEventListener("click", listener);
        return lambda {
            document.removeEventListener("click", listener);
        };
    }, [onClickOutside]);

    <div className="fixed z-10 inset-0">
        <div className="absolute h-full w-full inset-0 bg-slate-500 opacity-75"></div>
        <div className="absolute top-24 bottom-0 w-full">
            <div
                ref={contentEl}
                className={classnames(
                    "relative h-full w-full mx-auto bg-white rounded-t-3xl",
                    {
                        "max-w-screen-sm": maxWidth == "sm",
                        "max-w-screen-md": maxWidth == "md",
                        "max-w-screen-lg": maxWidth == "lg"
                    }
                )}
            >
                {children}
            </div>
        </div>
    </div>
}

