def:pub isType(value: object, type: str | None = None) -> str | bool {
    if type is not None {
        if type == "Object" {
            return isinstance(value, dict);
        }
        if type == "Array" {
            return isinstance(value, list);
        }
        if type == "String" {
            return isinstance(value, str);
        }
        if type == "Number" {
            return isinstance(value, int) or isinstance(value, float);
        }
        if type == "Boolean" {
            return isinstance(value, bool);
        }
        return False;
    }
    if isinstance(value, dict) {
        return "Object";
    }
    if isinstance(value, list) {
        return "Array";
    }
    if isinstance(value, str) {
        return "String";
    }
    if isinstance(value, bool) {
        return "Boolean";
    }
    if isinstance(value, int) or isinstance(value, float) {
        return "Number";
    }
    return str(type(value).__name__);
}

def:pub assign(a: dict[str, object], b: dict[str, object]) -> dict[str, object] {
    if isType(a, "Object") and isType(b, "Object") {
        for key in b {
            a_val = a[key];
            b_val = b[key];
            if (isType(a_val) != isType(b_val)) or not isType(a_val, "Object") {
                a[key] = b_val;
            } else {
                a[key] = assign(
                    a_val as dict[str, object],
                    b_val as dict[str, object]
                );
            }
        }
    }
    return a;
}

