    }
    if secure {
        parts.append("Secure");
    }
    if maxAge is not None {
        parts.append(f"Max-Age={maxAge}");
    }
    return "; ".join(parts);
}

def buildRemoveCookieString(key: str, config: CookieConfig) -> str {
    sameSite = config.sameSite if config.sameSite is not None else DEFAULT_SAME_SITE;
    secure = resolveSecure(config, sameSite);
    parts: list[str] = [
        f"{key}=",
        f"Path={config.path if config.path is not None else DEFAULT_PATH}",
        f"SameSite={capitalizeSameSite(sameSite)}",
        "Max-Age=0",
    ];
    if config.domain {
        parts.append(f"Domain={config.domain}");
    }
    if secure {
        parts.append("Secure");
    }
    return "; ".join(parts);
}

def resolveDocument() -> object {
    if document is None {
        raise StorageError("Cookie storage is not available in this environment");
    }
    return document;
}

class CookieStorageAdapter {
    has config: CookieConfig = CookieConfig();

    def init(config: CookieConfig | None = None) {
        if config is not None {
            self.config = config;
        }
    }

    def get(key: str) -> str | None {
        doc = resolveDocument();
        cookies = parseCookieString((doc as dict)["cookie"] as str);
        return cookies.get(key);
    }

    def set(key: str, value: str) {
        doc = resolveDocument();
        (doc as dict)["cookie"] = buildCookieString(key, value, self.config);
    }

    def remove(key: str) {
        doc = resolveDocument();
        (doc as dict)["cookie"] = buildRemoveCookieString(key, self.config);
    }
}

