obj HandPromise {
    has executor_fn: Callable[[Callable[[object], None], Callable[[object], None]], None];
    has state: str = "pending";
    has value: object | None = None;
    has reason: object | None = None;
    has onFullfilledCallbacks: list[Callable[[object], None]] = [];
    has onRejectedCallbacks: list[Callable[[object], None]] = [];

    def postinit {
        resolve = lambda (value: object) -> None {
            if self.state == "pending" {
                self.state = "fulfilled";
                self.value = value;
                for cb in self.onFullfilledCallbacks {
                    cb(value);
                }
            }
        };
        reject = lambda (reason: object) -> None {
            if self.state == "pending" {
                self.state = "rejected";
                self.reason = reason;
                for cb in self.onRejectedCallbacks {
                    cb(reason);
                }
            }
        };
        self.executor_fn(resolve, reject);
    }

    def then(
        onFulfilled: Callable[[object], object] | None = None,
        onRejected: Callable[[object], object] | None = None
    ) -> HandPromise {
        if not callable(onFulfilled) {
            onFulfilled = lambda (value: object) -> object { return value; };
        }
        if not callable(onRejected) {
            onRejected = lambda (err: object) -> object { raise err as Exception; };
        }
        return HandPromise(executor_fn=lambda (resolve: Callable[[object], None], reject: Callable[[object], None]) -> None {
            if self.state == "fulfilled" {
                setTimeout(lambda {
                    try {
                        res = onFulfilled(self.value);
                        resolve(res);
                    } except Exception as error {
                        reject(error);
                    }
                });
            }
            if self.state == "rejected" {
                setTimeout(lambda {
                    try {
                        res = onRejected(self.reason);
                        resolve(res);
                    } except Exception as error {
                        reject(error);
                    }
                });
            }
            if self.state == "pending" {
                self.onFullfilledCallbacks.append(lambda (value: object) -> None {
                    setTimeout(lambda { _ = onFulfilled(value); });
                });
                self.onRejectedCallbacks.append(lambda (reason: object) -> None {
                    setTimeout(lambda { _ = onRejected(reason); });
                });
            }
        });
    }

    def catch(onRejected: Callable[[object], object]) -> HandPromise {
        return self.then(lambda (_value: object) -> object { return None; }, onRejected);
    }
}

