    isTimerActive: bool = False,
    onStartTimer: Callable[[], None],
    onStopTimer: Callable[[], None]
) -> JsxElement {
    totalHours = totalSeconds / 3600;
    progressWidth = 0.0;
    overEstimateCls = "font-medium text-status-success";
    overEstimateLabel = "";
    barCls = "h-2 rounded-full transition-all bg-accent-blue";
    if estimatedHours {
        progressWidth = min((totalHours / estimatedHours) * 100, 100);
        if totalHours > estimatedHours {
            overEstimateCls = "font-medium text-status-error";
            overEstimateLabel = f"Over by {(totalHours - estimatedHours):.1f}h";
            barCls = "h-2 rounded-full transition-all bg-accent-red";
        } else {
            overEstimateLabel = f"{(estimatedHours - totalHours):.1f}h remaining";
        }
    }

    <div className="space-y-4">
        <div className="bg-surface-light-elevated dark:bg-surface-dark rounded-lg p-4">
            <div className="flex items-center justify-between mb-3">
                <div>
                    <h3 className="text-sm font-semibold text-text-light-primary dark:text-text-dark-primary">
                        Total Time: {formatTime(totalSeconds)}
                    </h3>
                    <p className="text-xs text-text-light-secondary dark:text-text-dark-secondary">
                        {formatDuration(totalSeconds)}
                    </p>
                </div>
                {if isTimerActive {
                    <button
                        onClick={onStopTimer}
                        className="px-4 py-2 bg-status-error text-white text-sm font-medium rounded-lg hover:bg-status-error/90 transition-colors flex items-center gap-2"
                    >
                        <span className="animate-pulse">⏱️</span>
                        Stop Timer
                    </button>
                } else {
                    <button
                        onClick={onStartTimer}
                        className="px-4 py-2 bg-accent-blue text-white text-sm font-medium rounded-lg hover:bg-accent-blue-hover transition-colors flex items-center gap-2"
                    >
                        ▶️ Start Timer
                    </button>
                }}
            </div>
            {if estimatedHours {
                <div className="pt-3 border-t border-border-light dark:border-border-dark">
                    <div className="flex items-center justify-between text-xs">
                        <span className="text-text-light-secondary dark:text-text-dark-secondary">
                            Estimated: {estimatedHours}h
                        </span>
                        <span className={overEstimateCls}>{overEstimateLabel}</span>
                    </div>
                    <div className="mt-2 w-full bg-surface-light-elevated dark:bg-surface-dark-elevated rounded-full h-2">
                        <div
                            className={barCls}
                            style={{"width": f"{progressWidth}%"}}
                        />
                    </div>
                </div>
            }}
        </div>
        {if len(entries) > 0 {
            <div className="space-y-2">
                <h4 className="text-sm font-semibold text-text-light-primary dark:text-text-dark-primary">
