def:pub getExtension(extensionId: str, mustExist: bool) -> any | None {
    extension = frameworkStore.getState().extensions[extensionId];
    if mustExist {
        assertDefined(extension, f"Unknown extension '{extensionId}'.");
        return extension;
    }
    return extension;
}

