import from "classnames" { default as classNames }

def:pub Button(
    children: JsxElement | str | list[JsxElement | str],
    type: Literal["submit", "button"],
    width: Literal["full", "auto", "fit"],
    className: str | None = None,
    isLoading: bool = False,
    buttonStyle: Literal["primary", "secondary", "danger"] = "primary",
    background: bool = True,
) -> JsxElement {
    return (
        <button
            type={type}
            className={classNames(
                "px-4 py-4 disabled:cursor-not-allowed rounded-xl text-white hover:shadow-2xl transition-all",
                {"w-full": width == "full"},
                {"w-auto": width == "auto"},
                {"w-fit": width == "fit"},
                {
                    "bg-blue-500 hover:bg-blue-600 hover:shadow-blue-200 dark:hover:shadow-blue-700":
                        buttonStyle == "primary" and background,
                    "bg-gray-500 hover:bg-gray-600 hover:shadow-gray-200 dark:hover:shadow-gray-700 ":
                        buttonStyle == "secondary" and background,
                    "bg-red-500 hover:bg-red-600 hover:shadow-red-200 dark:hover:shadow-red-700":
                        buttonStyle == "danger" and background,
                },
                {
                    "text-blue-500 hover:text-blue-600":
                        buttonStyle == "primary" and not background,
                    "text-gray-500 hover:text-gray-600":
                        buttonStyle == "secondary" and not background,
                    "text-red-500 hover:text-red-600":
                        buttonStyle == "danger" and not background,
                },
                className,
            )}
        >
            {children}
        </button>
    );
}

