import from "./BaseWidget" { BaseWidget }

obj WikiThumbnail {
    has source: str;
}

obj WikiArticle {
    has title: str;
    has extract: str;
    has url: str;
    has thumbnail: WikiThumbnail | None = None;
}

def parse_article(data: dict[str, object]) -> WikiArticle {
    thumb = None;
    if "thumbnail" in data {
        thumb_raw = data["thumbnail"] as dict[str, str];
        thumb = WikiThumbnail(source=thumb_raw["source"]);
    }
    content_urls = data["content_urls"] as dict[str, dict[str, str]];
    return WikiArticle(
        title=data["title"] as str,
        extract=data["extract"] as str,
        url=content_urls["desktop"]["page"],
        thumbnail=thumb,
    );
}

def:pub WikipediaWidget() -> JsxElement {
    has article: WikiArticle | None = None;
    has loading: bool = True;
    has error: str | None = None;

    async def fetch_article() {
        loading = True;
        error = None;
        try {
            response = await fetch("https://en.wikipedia.org/api/rest_v1/page/random/summary");
            if not response.ok {
                raise ValueError("Failed to fetch");
            }
            data = await response.json() as dict[str, object];
            article = parse_article(data);
        } except Exception {
            error = "Failed to load article";
        } finally {
            loading = False;
        }
    }

    async can with entry {
        await fetch_article();
    }

    <BaseWidget title="Wikipedia" icon="📚" loading={loading} error={error} onRefresh={fetch_article}>
        {if article {
            <div className="space-y-3">
                {if article.thumbnail {
                    <img src={article.thumbnail.source} alt={article.title} className="w-full h-32 object-cover rounded-button transition-all duration-standard ease-smooth" />
                }}
                <div>
                    <h3 className="font-semibold text-text-light-primary dark:text-text-dark-primary mb-2">{article.title}</h3>
                    <p className="text-sm text-text-light-secondary dark:text-text-dark-secondary line-clamp-4">{article.extract}</p>
                </div>
                <a href={article.url} target="_blank" rel="noopener noreferrer" className="inline-block text-sm text-accent-blue hover:underline">Read more →</a>
            </div>
        }}
    </BaseWidget>
}

