def:pub parseTaskInput(input: str) -> dict[str, object] {
    text: str = input.strip();
    tags: list[str] = [];
    assignees: list[str] = [];
    priority: str | None = None;
    dueDate: str | None = None;
    project: str | None = None;
    for match in re.finditer(r"#([a-zA-Z][a-zA-Z0-9-]*)", text) {
        tag: str = match.group(1);
        if tag not in tags {
            tags = tags + [tag];
        }
        text = text.replace(match.group(0), " ");
    }
    for match in re.finditer(r"!([a-zA-Z0-9]+)", text) {
        priority = parsePriority(match.group(1));
        text = text.replace(match.group(0), " ");
    }
    for match in re.finditer(r"@([a-zA-Z0-9_-]+)", text) {
        assignees = assignees + [match.group(1)];
        text = text.replace(match.group(0), " ");
    }
    for match in re.finditer(r"\^([a-zA-Z0-9_-]+)", text) {
        project = match.group(1);
        text = text.replace(match.group(0), " ");
    }
    lowerText = text.lower();
    dueIdx = lowerText.find("due ");
    if dueIdx != -1 {
        rest = text[dueIdx + 4:].strip();
        duePart = rest.split()[0];
        dueDate = parseDueDate(duePart);
        text = (text[:dueIdx] + rest[len(duePart):]).strip();
    }
    title = re.sub(r"\s+", " ", text).strip();
    return {
        "title": title,
        "tags": tags,
        "priority": priority,
        "dueDate": dueDate,
        "assignees": assignees,
        "project": project,
    };
}

