def SparkleLinkParticleGroup() -> JsxElement {
    has particles: list[dict[str, int | dict[str, str]]] = [];

    can with entry {
        delay_val = str(RANDOM(1, 10));
        alpha_val = str(RANDOM(40, 90) / 100);
        ox: int = RANDOM(300, 800);
        if Math.random() > 0.5 { ox = -ox; }
        oy: int = RANDOM(300, 800);
        if Math.random() > 0.5 { oy = -oy; }
        size_val = str(RANDOM(40, 90) / 100);
        new_particles: list[dict[str, int | dict[str, str]]] = [];
        for i in range(20) {
            new_particles.append({
                "id": i,
                "style": {
                    "--x": str(RANDOM(20, 80)),
                    "--y": str(RANDOM(20, 80)),
                    "--duration": str(RANDOM(10, 30)),
                    "--delay": delay_val,
                    "--alpha": alpha_val,
                    "--origin-x": f"{ox}%",
                    "--origin-y": f"{oy}%",
                    "--size": size_val
                }
            });
        }
        particles = new_particles;
    }

    return <>{for p in particles { <SparkleLinkParticle key={str(p["id"])} style={p["style"] as dict[str, str]} /> }}</>;
}

