    return url is not None and url != "";
}

def:pub isFolder(bookmark: NormalizedDynamicBookmark | None) -> bool {
    if bookmark is None {
        return True;
    }
    url = bookmark.url;
    return url is None or url == "";
}

def:pub isRoot(bookmark: NormalizedDynamicBookmark | None) -> bool {
    if bookmark is None {
        return False;
    }
    return bookmark.id == "0";
}

def:pub isTracked(bookmark: NormalizedDynamicBookmark | None) -> bool {
    if bookmark is None {
        return False;
    }
    regExp = bookmark.regExp;
    return regExp is not None and regExp != "";
}

def:pub isOnlyOneFile(lhs: NormalizedDynamicBookmark | None, rhs: NormalizedDynamicBookmark | None) -> bool {
    return isFile(lhs) != isFile(rhs);
}

