import from "radix-ui" { ScrollArea as ScrollAreaPrimitive }
import from ..lib.utils { cn }

def:pub ScrollArea(props: dict[str, object]) -> JsxElement {
    <ScrollAreaPrimitive.Root
        {**props}
        data-slot="scroll-area"
        className={cn("relative overflow-hidden", props["className"] as str)}
    >
        <ScrollAreaPrimitive.Viewport
            data-slot="scroll-area-viewport"
            className="h-full w-full rounded-[inherit] [&>div]:!block"
        >
            {props["children"]}
        </ScrollAreaPrimitive.Viewport>
        <ScrollBar />
        <ScrollAreaPrimitive.Corner />
    </ScrollAreaPrimitive.Root>
}

def:pub ScrollBar(props: dict[str, object]) -> JsxElement {
    orientation = props["orientation"];
    if not orientation {
        orientation = "vertical";
    }
    <ScrollAreaPrimitive.ScrollAreaScrollbar
        {**props}
        data-slot="scroll-area-scrollbar"
        data-orientation={orientation}
        orientation={orientation as str}
        className={cn(
            "flex touch-none select-none transition-colors",
            "h-full w-2.5 border-l border-l-transparent p-px" if orientation == "vertical" else "",
            "h-2.5 flex-col border-t border-t-transparent p-px" if orientation == "horizontal" else "",
            props["className"] as str
        )}
    >
        <ScrollAreaPrimitive.ScrollAreaThumb
            data-slot="scroll-area-thumb"
            className="relative flex-1 rounded-full bg-primary/20 hover:bg-primary/40 transition-colors"
        />
    </ScrollAreaPrimitive.ScrollAreaScrollbar>
}

