import from "react" { useState, useEffect }

def:pub useIsDesktop(breakpoint: int = 768) -> bool {
    has isDesktop: bool = window.innerWidth > breakpoint if window else True;

    useEffect(lambda {
        def handle_resize() {
            isDesktop = window.innerWidth > breakpoint;
        }
        window.addEventListener("resize", handle_resize);
        handle_resize();
        return lambda { window.removeEventListener("resize", handle_resize); };
    }, [breakpoint]);

    isDesktop
}

