# from: leonardtng__cryptoscapes::common/helpers/cacheStorageHandler.ts
def:pub cacheWithExpiry(key: str, data: object, expiryTime: int) -> None {
    now = new(Date);
    item = {"value": data, "expiry": now.getTime() + expiryTime};
    try {
        localStorage.setItem(key, JSON.stringify(item));
    } except Exception {
        console.log("Local Storage Full");
    }
}

def:pub retrieveCache(key: str) -> object | None {
    itemStr = localStorage.getItem(key);
    if not itemStr {
        return None;
    }
    item = JSON.parse(itemStr);
    now = new(Date);
    if now.getTime() > item["expiry"] {
        localStorage.removeItem(key);
        return None;
    }
    return item["value"];
}

