import math;
import time;

obj Artifact {
    has id: str;
    has name: str;
    has type: str;
    has path: str;
    has createdAt: int;
}

def asNum(v: object | None) -> float | None {
    if isinstance(v, (int, float)) and math.isfinite(v) {
        return v;
    }
    return None;
}

def toArtifact(raw: dict[str, object]) -> Artifact {
    created_raw = raw.get("created_at", raw.get("createdAt"));
    created_num = asNum(created_raw);
    created_at: int = int(created_num) if created_num is not None else int(time.time() * 1000);
    return Artifact(
        id=str(raw.get("id", raw.get("artifact_id", ""))),
        name=str(raw.get("name", raw.get("filename", raw.get("id", "Artifact")))),
        type=str(raw.get("type", raw.get("content_type", "file"))),
        path=str(raw.get("path", raw.get("url", raw.get("id", "")))),
        createdAt=created_at,
    );
}

