def applySpacing(style: dict[str, object], props: dict[str, object]) -> None {
    gap = props.get("gap");
    margin = props.get("margin");
    marginX = props.get("marginX");
    marginY = props.get("marginY");
    marginTop = props.get("marginTop");
    marginRight = props.get("marginRight");
    marginBottom = props.get("marginBottom");
    marginLeft = props.get("marginLeft");
    padding = props.get("padding");
    paddingX = props.get("paddingX");
    paddingY = props.get("paddingY");
    paddingTop = props.get("paddingTop");
    paddingRight = props.get("paddingRight");
    paddingBottom = props.get("paddingBottom");
    paddingLeft = props.get("paddingLeft");
    resolvedGap = toCssSpace(gap);
    if resolvedGap is not None {
        style["gap"] = resolvedGap;
    }
    resolvedMargin = toCssSpace(margin);
    if resolvedMargin is not None {
        style["margin"] = resolvedMargin;
    }
    resolvedMarginX = toCssSpace(marginX);
