import from "react" { useEffect, useRef, useState }

def:pub useClickOutside() -> dict[str, object] {
    openState = useState(False);
    open: bool = openState[0] as bool;
    setOpen = openState[1] as Callable[[bool], None];
    containerRef = useRef(None);
    def handleClickOutside(event: MouseEvent) {
        if containerRef.current and containerRef.current.contains(event.target as object) {
            setOpen(False);
        }
    }
    useEffect(lambda {
        document.addEventListener("click", handleClickOutside, True);
        return lambda { document.removeEventListener("click", handleClickOutside, True); };
    }, []);
    return {"open": open, "setOpen": setOpen, "containerRef": containerRef};
}

