        {"title": "Today's Revenue", "value": formatCurrency(todayRevenue), "icon": "💲", "color": "text-success", "bgColor": "bg-success/10"},
        {"title": "Menu Items", "value": str(totalMenuItems), "icon": "🍴", "color": "text-accent-secondary", "bgColor": "bg-accent-secondary/10"},
    ];

    <div className="space-y-6">
        <div>
            <h2 className="text-2xl font-bold text-text mb-2">Dashboard</h2>
            <p className="text-text-secondary">
                Welcome back! Here's your restaurant overview
            </p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {for (i, stat) in enumerate(statCards) {
                <Card key={str(i)} className="hover:shadow-lg transition-shadow">
                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-text-secondary text-sm mb-1">{stat["title"]}</p>
                            <p className="text-2xl font-bold text-text">{stat["value"]}</p>
                        </div>
                        <div className={f"{stat['bgColor']} p-3 rounded-lg"}>
                            <span className={f"w-6 h-6 {stat['color']} text-xl"}>{stat["icon"]}</span>
                        </div>
                    </div>
                </Card>
            }}
        </div>
        <Card>
            <h3 className="text-lg font-semibold text-text mb-4">Quick Actions</h3>
            <div className="grid sm:grid-cols-3 gap-4">
                <a href="/restaurant/orders" className="p-4 border border-border rounded-lg hover:border-accent hover:bg-accent/5 transition-colors text-center">
                    <span className="w-8 h-8 text-accent mx-auto mb-2 block text-2xl">🛍️</span>
                    <p className="font-medium text-text">View Orders</p>
                    <p className="text-sm text-text-secondary">Manage incoming orders</p>
