def:pub PageIndicator(no: int, count: int, onUpdate: Callable[[int], None]) -> JsxElement {
    blocks = useMemo(lambda () -> list[dict[str, str]] {
        if count <= 0 {
            return [];
        }
        r: list[dict[str, str]] = [];
        for i in range(count) {
            r.append({
                "className": "scroll-thumb" if i == no else "scroll-block",
                "title": str(i + 1),
            });
        }
        return r;
    }, [count, no]);

    onSelect = useCallback(lambda (ev: MouseEvent) -> None {
        target = ev.target;
        onUpdate(int(target.title) - 1);
    }, [onUpdate]);

    <div className="page-indicator">
        <div className="label">{no + 1} / {count}</div>
        <div className="scroll-bar">
            {for block in blocks {
                <div key={block["title"]} className={block["className"]} title={block["title"]} onClick={onSelect}></div>
            }}
        </div>
    </div>
}

