# Language: Jac
# from: cenksari__react-seatmap-creator::components/Header.tsx
obj ISeatMap {
    has name: str = "";
    has venueName: str = "";
    has blockName: str = "";
}

def:pub Header(seatMap: ISeatMap | None = None, editMapName: Callable[[str], None] | None = None) -> JsxElement {
    has name: str = seatMap.name if seatMap is not None else "";

    def handleOnSubmit(e: FormEvent) {
        e.preventDefault();
        if not name or name.strip() == "" {
            return;
        }
        if editMapName {
            editMapName(name);
        }
    }

    def handleNameChange(e: ChangeEvent) {
        name = e.target.value;
    }

    venueLabel = seatMap.venueName if seatMap is not None else "";
    blockLabel = seatMap.blockName if seatMap is not None else "";
    tooltipHtml = f"<p><strong>Venue name</strong><br />{venueLabel}</p><p>&nbsp;</p><p><strong>Block name</strong><br />{blockLabel}</p>";

    <header className="flex flex-space-between flex-v-center">
        <form noValidate className="flex flex-gap-medium" onSubmit={handleOnSubmit}>
            <input
                id="name"
                type="text"
                name="mapName"
                autoComplete="off"
                value={name}
                placeholder="Enter seat map name"
                onChange={handleNameChange}
            />
            <button type="submit" className="button black">Save</button>
        </form>
        <div>
            <button
                type="button"
                data-tooltip-id="description"
                className="flex flex-gap-small flex-v-center button gray"
                data-tooltip-html={tooltipHtml}
            >
                <span className="material-symbols-outlined">info</span>
            </button>
        </div>
    </header>
}

