def:pub Progress(
    className: str | None = None,
    percent: int | float = 0,
    unfilled: bool = True,
    inactive: bool = False,
    info: bool = False,
    sliderWidth: int | float = 2,
    textColor: str = "#000",
    sliderColor: str | None = None,
    style: dict[str, object] | None = None,
    barStyle: dict[str, object] | None = None,
) -> JsxElement {
    inactiveColor = "#CCC";
    styleVal = style if style is not None else {};
    barStyleVal = barStyle if barStyle is not None else {};
    wrapCls = classnames(f"{prefixCls}-outer", className, {f"{prefixCls}-hide-outer": not unfilled});
    percentStyle = {"width": f"{percent}%", "height": 0};
    mergedBarStyle = {**barStyleVal, "borderWidth": sliderWidth, "borderColor": inactiveColor if inactive else (sliderColor if sliderColor is not None else inactiveColor)};
    barCombined = {**mergedBarStyle, **percentStyle};
    textStyle = {"color": inactiveColor if inactive else textColor};
    <div className={prefixCls}>
        <div style={styleVal} className={wrapCls} role="progressbar" aria-valuenow={percent} aria-valuemin={0} aria-valuemax={100}>
            <div className={f"{prefixCls}-bar"} style={barCombined} />
        </div>
        {if info {
            <div className={f"{prefixCls}-text"} style={textStyle}>{percent}%</div>
        }}
    </div>
}

