obj FieldData {
    has name: str;
    has display_value: str;
    has type: str;
    has isRequired: bool = False;
}

def:pub StandardInput(
    fieldData: FieldData,
    editObj: dict[str, str] | None = None,
    errors: dict[str, object] | None = None
) -> JsxElement {
    name = fieldData.name;
    defaultValue = "";
    if editObj is not None and name in editObj and editObj[name] {
        defaultValue = editObj[name];
    }
    fieldErrors = errors or {};
    hasError = name in fieldErrors and fieldErrors[name];
    errorBlock = <p>This is required</p> if hasError else None;
    return (
        <div
            style={{
                "display": "flex",
                "alignItems": "left",
                "justifyContent": "left",
                "flexDirection": "column",
                "textAlign": "left",
                "marginBottom": "12px"
            }}
        >
            <label htmlFor={fieldData.name} className="labelTitle">
                {fieldData.display_value}
            </label>
            <input
                type={fieldData.type}
                className="textInput"
                defaultValue={defaultValue}
            />
            {errorBlock}
        </div>
    );
}

