import re;

def:pub isValidOtp(otp: str) -> bool {
    return re.match(r"^([A-Z0-9]{6})$", str(otp.strip())) is not None;
}

def:pub hasSpecialChar(char: str) -> bool {
    return re.search(r"[`!@#$%^&*()_+\-=\[\]{};':\"\\|,.<>\/?~]", char) is not None;
}

obj PasswordValidationResult {
    has score: int = 0;
    has strength: str = "";
    has hasSixChar: bool = False;
    has hasLowerCase: bool = False;
    has hasUpperCase: bool = False;
    has hasNumericChar: bool = False;
    has hasSpecialChar: bool = False;
    has maxThirtySixChar: bool = False;
    has isValid: bool = False;
}

def:pub validatePassword(value: str) -> PasswordValidationResult {
    res = PasswordValidationResult();
    if len(value) >= 6 {
        res.score = res.score + 1;
        res.hasSixChar = True;
    }
    if len(value) > 0 and len(value) <= 36 {
        res.score = res.score + 1;
        res.maxThirtySixChar = True;
    }
    for char in value {
        if char >= "A" and char <= "Z" and not res.hasUpperCase {
            res.score = res.score + 1;
            res.hasUpperCase = True;
        } elif char >= "a" and char <= "z" and not res.hasLowerCase {
            res.score = res.score + 1;
            res.hasLowerCase = True;
        } elif char >= "0" and char <= "9" and not res.hasNumericChar {
            res.score = res.score + 1;
            res.hasNumericChar = True;
        } elif hasSpecialChar(char) and not res.hasSpecialChar {
            res.score = res.score + 1;
            res.hasSpecialChar = True;
        }
    }
    if res.score <= 2 {
        res.strength = "Weak";
    } elif res.score <= 4 {
        res.strength = "Good";
    } elif res.score <= 5 {
        res.strength = "Strong";
    } else {
        res.strength = "Very Strong";
    }
    res.isValid = (
        bool(res.score)
        and bool(res.strength)
        and res.hasSixChar
        and res.hasLowerCase
        and res.hasUpperCase
        and res.hasNumericChar
        and res.hasSpecialChar
        and res.maxThirtySixChar
    );
    return res;
}

