        }}
        {if onBackgroundImage {
            <button onClick={onBackgroundImage} className={inactive_action_class()} title="Background Image">
                <ImagePlus className="w-4 h-4" />
            </button>
        }}
        <span className="ml-auto text-xs text-text-light-tertiary dark:text-text-dark-tertiary px-2">
            {slideCount} {"slide" if slideCount == 1 else "slides"}
