# from: adbutterfield__react-content-font::reducer.ts
import from .create_font_link_tags { createFontLinkTags }
import type from .create_font_link_tags { FontWeights, Display }

obj State {
    has fontName: str;
    has linkTags: list[JsxElement];
    has requestedChars: set[str];
    has display: Display;
    has isFontUpdating: bool;
    has isFontLoaded: bool;
    has fontWeights: FontWeights | None = None;
}

obj InitializeAction {
    has uniqueChars: set[str];
    has onLoad: Callable[[], None];
    has type: str = "INITIALIZE";
}

obj AddLinkTagAction {
    has newChars: set[str];
    has onLoad: Callable[[], None];
    has type: str = "ADD_LINK_TAG";
}

obj FontUpdatingAction {
    has type: str = "FONT_UPDATING";
}

obj FontUpdatedAction {
    has type: str = "FONT_UPDATED";
}

obj FontLoadedAction {
    has type: str = "FONT_LOADED";
}

type Action = InitializeAction | AddLinkTagAction | FontUpdatingAction | FontUpdatedAction | FontLoadedAction;

def reducer(state: State, action: Action) -> State {
    match action.type {
        case "INITIALIZE":
            init = action as InitializeAction;
            linkTags = createFontLinkTags(
                fontName=state.fontName,
                newChars=list(init.uniqueChars),
                onLoad=init.onLoad,
                display=state.display,
                fontWeights=state.fontWeights,
            );
            return State(
                fontName=state.fontName,
                linkTags=state.linkTags + linkTags,
                requestedChars=init.uniqueChars,
                display=state.display,
                isFontUpdating=state.isFontUpdating,
                isFontLoaded=state.isFontLoaded,
                fontWeights=state.fontWeights,
            );
        case "ADD_LINK_TAG":
            add = action as AddLinkTagAction;
            newChars = [char for char in list(add.newChars) if char not in state.requestedChars];
            if len(newChars) > 0 {
                newLinkTags = createFontLinkTags(
                    fontName=state.fontName,
                    newChars=newChars,
                    onLoad=add.onLoad,
                    display=state.display,
                    fontWeights=state.fontWeights,
                );
                merged = set(list(state.requestedChars) + newChars);
                return State(
                    fontName=state.fontName,
                    linkTags=state.linkTags + newLinkTags,
                    requestedChars=merged,
                    display=state.display,
                    isFontUpdating=True,
                    isFontLoaded=state.isFontLoaded,
                    fontWeights=state.fontWeights,
                );
            }
            return State(
                fontName=state.fontName,
                linkTags=state.linkTags,
                requestedChars=state.requestedChars,
                display=state.display,
                isFontUpdating=False,
                isFontLoaded=state.isFontLoaded,
                fontWeights=state.fontWeights,
            );
        case "FONT_UPDATING":
            return State(
                fontName=state.fontName,
                linkTags=state.linkTags,
                requestedChars=state.requestedChars,
                display=state.display,
                isFontUpdating=True,
                isFontLoaded=state.isFontLoaded,
                fontWeights=state.fontWeights,
            );
        case "FONT_UPDATED":
            return State(
                fontName=state.fontName,
                linkTags=state.linkTags,
                requestedChars=state.requestedChars,
                display=state.display,
                isFontUpdating=False,
                isFontLoaded=state.isFontLoaded,
                fontWeights=state.fontWeights,
            );
        case "FONT_LOADED":
            return State(
                fontName=state.fontName,
                linkTags=state.linkTags,
                requestedChars=state.requestedChars,
                display=state.display,
                isFontUpdating=state.isFontUpdating,
                isFontLoaded=True,
                fontWeights=state.fontWeights,
            );
        case _:
            return state;
    }
}

