import type from "@/core/types" { Extension, ExtensionModule }
import from "@/core/extension/set" { setExtensionStatus }
import from "@/core/extension-context/impl" { ExtensionContextImpl }
import from "@/core/extension-context/get" { getExtensionContext }
import from "@/util/log" { Logger }
import importlib;

glob LOG = Logger.getLogger("extendit/core");

async def:pub activateExtension(extensionId: str) -> Extension {
    ctx = getExtensionContext(extensionId, True);
    extension = ctx.extension;
    if extension.status != "inactive" {
        return extension;
    }
    dependencies = await getExtensionDependencies(extension);
    extension = ctx.extension;
    if extension.status != "inactive" {
        return extension;
    }
    try {
        exports: object | None = None;
        module: ExtensionModule | None = ctx.module;
        if not module {
            modulePath = extension.manifest.main;
            if modulePath {
                extension = setExtensionStatus(extensionId, "loading");
                module = await importModule(ctx, modulePath);
            }
        }
        if module {
            extension = setExtensionStatus(extensionId, "activating");
            activateFn = module?.activate;
            if activateFn and callable(activateFn) {
                exports = await activateFn(ctx, *dependencies);
            }
        }
        extension = setExtensionStatus(extensionId, "active", exports);
    } except Exception as error {
        LOG.error(
            f"An error occurred during activation of extension '{extensionId}':",
            error
        );
        extension = setExtensionStatus(extensionId, "rejected", error);
    }
    return extension;
}

async def getExtensionDependencies(extension: Extension) -> list[object] {
    extensionDependencies = extension.manifest.extensionDependencies;
    exportsArray: list[object] = [];
    if extensionDependencies and len(extensionDependencies) > 0 {
        errors: list[Exception] = [];
        for dependencyId in (extensionDependencies as list[str]) {
            dependency = await activateExtension(dependencyId);
            if dependency.status == "active" {
                exportsArray.append(dependency.exports);
            } elif dependency.reasons {
                errors = errors + dependency.reasons;
            }
        }
        if (
            len(errors) > 0
            or len(exportsArray) < len(extensionDependencies)
        ) {
            setExtensionStatus(
                extension.id,
                "rejected",
                f"Extension '{extension.id}' rejected because dependencies could not be resolved.",
                *errors
            );
        }
    }
    return exportsArray;
}

async def importModule(ctx: ExtensionContextImpl, path: str) -> ExtensionModule {
    resolvedPath = ctx.resolveModulePath(path);
    LOG.debug("Importing extension module", resolvedPath);
    pyModule = importlib.import_module(resolvedPath);
    module = pyModule as ExtensionModule;
    LOG.debug("Loaded extension module", resolvedPath);
    ctx.setModulePath(resolvedPath);
    ctx.setModule(module);
    return module;
}

