def reducer(state: dict[str, object], action: dict[str, object]) -> dict[str, object] {
    actionType = action["type"] as str;
    if actionType == "companies/pending" {
        return {**state, "status": "LOADING"};
    }
    if actionType == "companies/fulfilled" {
        return {**state, "status": "IDLE", "value": action["payload"]};
    }
    if actionType == "companies/rejected" {
        return {**state, "status": "FAILED", "error": action["error"]["message"]};
    }
    return state;
}

