# from: travisjneuman__neumanos::widgets/Dashboard/ClipboardWidget.tsx
import from .BaseWidget { BaseWidget }

def:pub ClipboardWidget() -> JsxElement {
    has history: list[str] = [];

    async def copy_to_clipboard(text: str) {
        try {
            await navigator.clipboard.writeText(text);
        } except Exception {
            console.error("Failed to copy");
        }
    }

    async def paste_from_clipboard() {
        try {
            text = await navigator.clipboard.readText();
            if text and text not in history {
                kept = history[0:9] if len(history) > 9 else history;
                history = [text] + kept;
            }
        } except Exception {
            console.error("Failed to paste");
        }
    }

    def clear_history() {
        history = [];
    }

    <BaseWidget title="Clipboard" icon="📋">
        <div className="space-y-3">
            <div className="flex gap-2">
                <button
                    onClick={paste_from_clipboard}
                    className="flex-1 px-4 py-2 bg-accent-blue hover:bg-accent-blue-hover text-white rounded-button text-sm font-medium transition-all duration-standard ease-smooth"
                >
                    Save Clipboard
                </button>
                <button
                    onClick={clear_history}
                    className="px-4 py-2 bg-surface-light-elevated dark:bg-surface-dark hover:bg-surface-light dark:hover:bg-surface-dark-elevated text-text-light-primary dark:text-text-dark-primary rounded-button text-sm font-medium transition-all duration-standard ease-smooth"
                >
                    Clear
                </button>
            </div>
            <div className="space-y-2 max-h-64 overflow-y-auto">
                {for (idx, item) in enumerate(history) {
                    <button
                        key={str(idx)}
                        onClick={lambda { copy_to_clipboard(item); }}
                        className="w-full text-left p-2 bg-surface-light-elevated dark:bg-surface-dark rounded-button hover:bg-surface-light dark:hover:bg-surface-dark-elevated transition-all duration-standard ease-smooth"
