# from: TeamCooks__TwoSpoon::hooks/usePageNum.ts
import from math { ceil }

def:pub usePageNum(
    totalResults: int,
    limit: int,
    currentPage: int,
) -> dict[str, int | bool] {
    lastPageNum = ceil(totalResults / limit);
    pageStartNum = max(currentPage - 2, 1);
    pageEndNum = min(currentPage + 2, lastPageNum);
    pageLength = pageEndNum - pageStartNum + 1;
    moreThanFirst = currentPage > 3;
    lessThanLast = currentPage < lastPageNum - 2;
    return {
        "pageStartNum": pageStartNum,
        "pageEndNum": pageEndNum,
        "moreThanFirst": moreThanFirst,
        "lessThanLast": lessThanLast,
        "pageLength": pageLength,
    };
}

