async def:pub GET(
    user_id: str,
    business_id: str | None = None,
    manager_cost: float | None = None,
    user_coins: float | None = None,
    business_quantity: float | None = None,
) -> dict[str, str] {
    userId = user_id;
    businessId = business_id;
    managerCost = manager_cost if manager_cost is not None else 0.0;
    userCoins = user_coins if user_coins is not None else 0.0;
    businessQuantity = business_quantity if business_quantity is not None else 0.0;
    managerOwned = False;
    if managerOwned {
        return {"error": "Already own a manager"};
    }
    if userCoins < managerCost {
        return {"error": "Not enough coins"};
    }
    if businessQuantity < 1 {
        return {"error": "Must have at least 1 of this business"};
    }
    try {
        player = {"id": userId};
        business = {"id": businessId if businessId is not None else "", "managerOwned": True};
        if business and player {
            return {"success": "Manager hired!"};
        }
    } except Exception {
        return {"error": "Something went wrong"};
    }
    return {};
}

