# from: bimcc__gantt-planing-network::component/gantt-task/time-scaled/DashedLine.tsx
import from ...types.bar_task { VirtualNode }
import from ..helpers.bar_helper { getUuid }

def:pub DashedLine(model: VirtualNode) -> JsxElement {
    svgEle: list[JsxElement] = [];
    sX: int = (model.sX if model.sX else 0) - 5;
    sY: int = model.sY if model.sY else 0;
    eX: int = (model.eX if model.eX else 0) - 3;
    eY: int = model.eY if model.eY else 0;
    i: int = -33;
    if sY > eY {
        i = -7;
    }
    sY = sY - 21;
    eY = eY + i;
    path: str = "";

    if sY == eY {
        path = f"""
     M {sX} {sY}
     h {eX - sX}
    """;
    } else {
        path = f"""
     M {sX} {sY}
     h {eX - sX}
     v {eY - sY}
    """;
        if model.flag {
            path = f"""
       M {sX} {sY}
       h {eX - sX}
       v {eY - sY}
      """;
        } elif sX >= eX {
            path = f"""
        M {sX} {sY}
        h 5
        v {(eY - sY) / 2}
        h {eX - sX}
        v {(eY - sY) / 2}
      """;
        }
    }

    svgEle = svgEle + [
        <path
            key={getUuid()}
            strokeWidth="1.5"
            d={path}
            strokeDasharray="2 2"
            fill="none"
        />
    ];

    <g className="arrow" fill="grey" stroke="grey">
        {svgEle}
    </g>
}

