import math;

obj JsDate {
    def getTime() -> int;
    def getFullYear() -> int;
    def getMonth() -> int;
    def toLocaleDateString() -> str;
}

def:pub daysBetween(startingDate: JsDate, lastestDate: JsDate | None = None) -> int {
    if not lastestDate {
        return 0;
    }
    difference = lastestDate.getTime() - startingDate.getTime();
    return int(math.ceil(difference / ((1000 * 3600) * 24)));
}

def:pub isInTheCurrentYear(date: JsDate) -> bool {
    return (Date() as JsDate).getFullYear() == date.getFullYear(); # jac:ignore[W2001,E1001]
}

def:pub monthsBetween(startingDate: JsDate, lastestDate: JsDate | None = None) -> int {
    if not lastestDate {
        return 0;
    }
    months = (lastestDate.getFullYear() - startingDate.getFullYear()) * 12;
    months -= startingDate.getMonth();
    months += lastestDate.getMonth();
    return 0 if months <= 0 else months;
}

def:pub getNowDate() -> str {
    now = Date() as JsDate; # jac:ignore[W2001,E1001]
    return now.toLocaleDateString();
}

