import from "react" { useCallback, useRef }

def:pub useEventCallback(fn: object) -> object {
    ref = useRef(fn);
    ref.current = fn;

    def stable(*args: object) -> object {
        f = ref.current;
        return f(*args);
    }

    return useCallback(stable, []);
}

