def get_color_class(value: int) -> str {
    if value >= 80 {
        return "text-[#4FBA1E]";
    }
    if value >= 60 {
        return "text-[#B7DD16]";
    }
    if value >= 40 {
        return "text-[#FDD101]";
    }
    if value >= 20 {
        return "text-[#FF8400]";
    }
    return "text-[#F02602]";
}

def format_date(timestamp: str) -> str {
    if not timestamp {
        return "";
    }
    date = new(Date, timestamp);
    return date.toLocaleDateString("en-US", {"month": "short", "day": "numeric", "year": "numeric"});
}

