def getScoreColor(score: float) -> str {
    if (score >= 75) {
        return "#22c55e";
    }
    if (score >= 50) {
        return "#eab308";
    }
    if (score >= 25) {
        return "#f97316";
    }
    return "#ef4444";
}

def getScoreTrailColor(score: float) -> str {
    if (score >= 75) {
        return "rgba(34, 197, 94, 0.15)";
    }
    if (score >= 50) {
        return "rgba(234, 179, 8, 0.15)";
    }
    if (score >= 25) {
        return "rgba(249, 115, 22, 0.15)";
    }
    return "rgba(239, 68, 68, 0.15)";
}

