}

def customMerge(defaultOptions: dict[str, object], options: dict[str, object]) -> dict[str, object] {
    axisStyles = getAxisStyle();
    xAxisStyle = axisStyles["xAxisStyle"] as dict[str, object];
    yAxisStyle = axisStyles["yAxisStyle"] as dict[str, object];
    xAxis = options.get("xAxis");
    if isinstance(xAxis, list) {
        options["xAxis"] = [merge(cloneDeep(xAxisStyle), el) for el in xAxis];
    }
    yAxis = options.get("yAxis");
    if isinstance(yAxis, list) {
        options["yAxis"] = [merge(cloneDeep(yAxisStyle), el) for el in yAxis];
    }
    return merge(defaultOptions, options);
}

