import from "datastore/collections/visualization/visualization.model" { Visualization, VisualizationStatus }

def:pub shouldInitializeAnimation(visualization: Visualization) -> bool {
    return (
        visualization.status == VisualizationStatus.Running
        and len(visualization.traversalPath) != 0
        and visualization.traversalPathIndex >= 0
        and visualization.traversalPathIndex < len(visualization.traversalPath)
    );
}

