import from "react" { useRef }
import from "use-clipboard-api" { useClipboardApi }

def:pub App() -> JsxElement {
    input_ref = useRef(None);
    (copied_value, copy, error) = useClipboardApi();

    async def handle_copy(e: MouseEvent) {
        if input_ref.current {
            value_to_copy = input_ref.current.value;
            success = await copy(value_to_copy);
            if success {
                console.log("Text copied:", copied_value);
            } else {
                console.error("Copy failed:", error);
            }
        }
    }

    <div>
        <input ref={input_ref} type="text" placeholder="Type something to copy" />
        <button onClick={handle_copy}>Copy to Clipboard</button>
        {if copied_value { <p>Copied: {copied_value}</p> }}
        {if error { <p style={{"color": "red"}}>Error: {error}</p> }}
    </div>
}

