def:pub isElementOutViewport(el: object) -> bool {
    rect = getattr(el, "getBoundingClientRect").call(None) as dict[str, float];
    return rect["bottom"] < 0 or rect["right"] < 0 or rect["left"] > window.innerWidth or rect["top"] > window.innerHeight;
}

