import from "@/shared/lib/browser/log" { checkAndHandleError }
import from "@/shared/lib/browser/getCurrentBrowser" { getCurrentBrowser }

type TabCallback = Callable[[str | None, dict[str, object] | None], None];
type WindowCallback = Callable[[dict[str, object] | None], None];
type TabCreateCallback = Callable[[dict[str, object]], None] | None;

def:pub getCurrentTab(done: TabCallback) {
    tabs = getCurrentBrowser().tabs;
    tabs.query({"active": True, "currentWindow": True}, lambda (tabList: list[dict[str, object]]) {
        if not checkAndHandleError(done) {
            currentTab = tabList[0];
            done(None, currentTab);
        }
    });
}

def:pub openNewTab(url: str | list[str], done: TabCreateCallback = None) {
    tabs = getCurrentBrowser().tabs;
    if isinstance(url, list) {
        for currUrl in url {
            tabs.create({"url": currUrl}, done);
        }
    } else {
        tabs.create({"url": url}, done);
    }
}

def:pub openNewWindow(url: str, done: WindowCallback = None) {
    windows = getCurrentBrowser().windows;
    windows.create({"url": url}, done);
}

def:pub openNewIncognitoWindow(url: str, done: WindowCallback = None) {
    windows = getCurrentBrowser().windows;
    windows.create({"url": url, "incognito": True}, done);
}

