# from: helderberto__use-clipboard-api::src/useClipboardApi.ts
import from "react" { useState }

obj DefaultClipboardService {
    async def write_text(text: str) -> None {
        if not navigator.clipboard {
            raise Exception("Clipboard not supported.");
        }
        await navigator.clipboard.writeText(text);
    }
}

obj ClipboardApi {
    has service: DefaultClipboardService;

    async def copy(value: str) -> None {
        await self.service.write_text(value);
    }
}

def:pub useClipboardApi() -> tuple[str | None, Callable[[str], Awaitable[bool]], str | None] {
    (copied_value, set_copied_value) = useState(None);
    (error, set_error) = useState(None);
    clipboard_api = ClipboardApi(service=DefaultClipboardService());

    async def copy(value: str) -> bool {
        try {
            await clipboard_api.copy(value);
            set_copied_value(value);
            set_error(None);
            return True;
        } except Exception as err {
            console.error("Failed to Copy", err);
            set_error(str(err));
            set_copied_value(None);
            return False;
        }
    }

    return (copied_value, copy, error);
}

