        <Heading style={heading}>New login detected</Heading>
        <Text style={paragraph}>Hi {name},</Text>
        <Text style={paragraph}>
            We detected a new login to your account. If this was you, no action is needed.
        </Text>
        <div style={detailsBox}>
            <Text style={detailsTitle}>Login details:</Text>
            <Text style={detailsText}>Time: {timestamp}</Text>
            {if ipAddress {
                <Text style={detailsText}>IP Address: {ipAddress}</Text>
            }}
            {if userAgent {
                <Text style={detailsText}>Device: {userAgent}</Text>
            }}
        </div>
        <Text style={paragraph}>
            If you didn't log in, please secure your account immediately by changing your password.
        </Text>
    </BaseEmail>;
}

