import from .constants { DELETE_METHOD, POST_METHOD, PUT_METHOD }

obj CallApiObject {
    has endpoint: str;
    has method: str;
    has data: object;
}

async def:pub call(
    apiObj: CallApiObject,
    onSuccess: Callable[[object], None] | None = None,
    onError: Callable[[], None] | None = None,
) {
    try {
        result = await fetch( # jac:ignore[W2001,W6002,E1032]
            str(window.location.origin) + apiObj.endpoint, # jac:ignore[W6002,E1032,E1055]
            {
                "method": apiObj.method,
                "body": JSON.stringify(apiObj.data), # jac:ignore[W6002,E1032]
                "headers": {"Content-Type": "application/json"},
            },
        );
        if onSuccess {
            onSuccess(result);
        }
    } except Exception as error {
        console.log(error); # jac:ignore[W6002,E1032]
        if onError {
            onError();
        }
    }
}

async def:pub makePost(
    data: object,
    endpoint: str,
    onSuccess: Callable[[object], None] | None = None,
    onError: Callable[[], None] | None = None,
) {
    await call(
        CallApiObject(endpoint=endpoint, method=POST_METHOD, data=data),
        onSuccess,
        onError,
    );
}

