import from lib.blog.views { trackBlogView }

async def:pub POST(body: dict[str, str]) -> dict[str, str | bool] {
    try {
        post_id = body.get("postId", "");
        if not post_id {
            return {"error": "Invalid postId"};
        }
        result = await trackBlogView(post_id) as dict[str, bool];
        if not result.get("success", False) {
            return {"error": "Failed to track view"};
        }
        return {"success": True};
    } except Exception as e {
        print(f"Error tracking view: {str(e)}");
        return {"error": "Internal server error"};
    }
}

