# from: dawangcoding__ClawUI::renderer/utils/formatRelativeTime.ts
def:pub formatRelativeTime(timestampMs: float | None) -> str {
    if (timestampMs is None or not Number.isFinite(timestampMs)) {
        return "未知";
    }
    now = Date.now();
    diffMs = now - timestampMs;
    absDiff = Math.abs(diffMs);
    suffix = "前" if diffMs >= 0 else "后";
    seconds = Math.floor(absDiff / 1000);
    if (seconds < 60) {
        return "刚刚";
    }
    minutes = Math.floor(seconds / 60);
    if (minutes < 60) {
        return f"{minutes}m {suffix}";
    }
    hours = Math.floor(minutes / 60);
    if (hours < 48) {
        return f"{hours}h {suffix}";
    }
    days = Math.floor(hours / 24);
    return f"{days}d {suffix}";
}

