def:pub useLocalVideoToggle() -> list[bool | Callable[[], None]] {
    has isPublishing: bool = False;

    room: object | None = None;
    videoTrack: LocalVideoTrack | None = None;

    async def get_local_video_track() -> LocalVideoTrack | None {
        return None;
    }

    def remove_local_video_track {
    }

    tracks_data = useTracksSettings();
    save_video_settings = tracks_data["saveVideoSettings"] as Callable[[bool], None];

    local_participant: object | None = None;
    if room {
        local_participant = (room as dict)["localParticipant"];
    }

    toggle_video_enabled = useCallback(lambda {
        if not isPublishing {
            if videoTrack {
                if local_participant {
                    local_track_publication = (local_participant as dict)["unpublishTrack"].call(None, videoTrack);
                    (local_participant as dict)["emit"].call(None, "trackUnpublished", local_track_publication);
                }
                remove_local_video_track();
                save_video_settings(False);
                return;
            }
            isPublishing = True;
            async def publish_track {
                try {
                    track = await get_local_video_track();
                    if track {
                        save_video_settings(True);
                        if local_participant {
                            (local_participant as dict)["publishTrack"].call(None, track, {"priority": "low"});
                        }
                    }
                } except Exception as error {
                    console.log(error);
                } finally {
                    isPublishing = False;
                }
            }
            publish_track();
        }
    }, [videoTrack, local_participant, isPublishing]);

    return [videoTrack is not None, toggle_video_enabled];
}

