def:pub formatValue(
    value: float,
    fractionDigits: int | None = None,
    options: dict[str, object] | None = None
) -> str {
    if fractionDigits is not None {
        return format(value, f".{fractionDigits}f");
    }
    if options is not None and "minimumFractionDigits" in options {
        digits = int(options["minimumFractionDigits"]);
        return format(value, f".{digits}f");
    }
    return str(value);
}

