) -> JsxElement {
    if not isOpen {
        return <></>;
    }

    sizeClass = "max-w-lg";
    if size == "sm" {
        sizeClass = "max-w-md";
    } elif size == "lg" {
        sizeClass = "max-w-2xl";
    } elif size == "xl" {
        sizeClass = "max-w-4xl";
    }

    def stop_prop(e: MouseEvent) {
        e.stopPropagation();
    }

    <div className="fixed inset-0 z-50 overflow-y-auto">
        <div className="fixed inset-0 bg-black/50 transition-opacity" onClick={onClose} />
        <div className="flex min-h-full items-center justify-center p-4">
            <div className={f"relative w-full {sizeClass} bg-white rounded-lg shadow-xl transform transition-all"} onClick={stop_prop}>
                {if title or showCloseButton {
                    <div className="flex items-center justify-between p-6 border-b border-border">
                        {if title {
                            <h2 className="text-xl font-bold text-text">{title}</h2>
                        }}
                        {if showCloseButton {
                            <button onClick={onClose} className="text-text-secondary hover:text-text transition-colors">
                                <svg className="w-6 h-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                    <path d="M18 6L6 18M6 6l12 12" />
                                </svg>
                            </button>
                        }}
                    </div>
                }}
                <div className="p-6">{children}</div>
            </div>
        </div>
    </div>
}

