import from "@/shared/constants/responseTypes" { default as responseTypes }
import type from "@/shared/types" { MessageResponse }

obj RequestMessage {
    has type: str | None = None;
    has data: object | None = None;
}

type SendResponse = Callable[[MessageResponse], None];
type RequestHandler = Callable[[RequestMessage, SendResponse], None];

def log(response: MessageResponse) {
    console.warn("response", response);
}

def defaultRequestHandler(request: RequestMessage, sendResponse: SendResponse = log) {
    sendResponse({
        "type": responseTypes.ERROR,
        "message": f"Could not handle request of type {request.type}",
    });
}

obj Router {
    has handlers: dict[str, RequestHandler] = {};

    def registerHandler(type: str, callback: RequestHandler) {
        self.handlers[type] = callback;
    }

    def getRequestHandler(type: str | None = None) -> RequestHandler {
        if type and type in self.handlers {
            return self.handlers[type];
        }
        return defaultRequestHandler;
    }

    def handleRequest(request: RequestMessage = RequestMessage(), sendResponse: SendResponse = log) {
        handle = self.getRequestHandler(request.type);
        handle(request, sendResponse);
    }
}

def:pub createRouter() -> Router {
    return Router();
}

