import from "react" { useCallback }
import from "@jac/runtime" { useNavigate }
import axios;
import from "react-hot-toast" { default as toast }
import from "@headlessui/react" { Dialog }
import from "react-icons/fi" { FiAlertTriangle }
import from "@/app/hooks/use-conversation" { default as useConversation }
import from "@/app/components/modals/modal" { default as Modal }
import from "@/app/components/button" { default as Button }

def:pub ConfirmModal(
    isOpen: bool = False,
    onClose: Callable[[], None]
) -> JsxElement {
    nav = useNavigate();
    conv = useConversation();
    conversationId = conv.conversationId as str;
    has isLoading: bool = False;

    on_delete = useCallback(lambda {
        isLoading = True;
        axios
            .delete(f"/api/conversations/{conversationId}")
            .then(lambda {
                onClose();
                nav("/conversations");
            })
            .catch(lambda {
                toast.error("Something went wrong.");
            })
            .finally(lambda {
                isLoading = False;
            });
    }, [conversationId, onClose]);

    <Modal isOpen={isOpen} onClose={onClose}>
        <div className="sm:flex sm:items-start">
            <div className="mx-auto flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-full bg-red-100 sm:mx-0 sm:h-10 sm:w-10">
                <FiAlertTriangle className="h-6 w-6 text-red-600" />
            </div>
            <div className="mt-3 text-center sm:ml-4 sm:mt-0 sm:text-left">
                <Dialog.Title
                    as="h3"
                    className="text-base font-semibold leading-6 text-gray-900"
                >
                    Delete Conversation
                </Dialog.Title>
                <div className="mt-2">
                    <p className="text-sm text-gray-500">
                        Are you sure you want to delete this conversation? This action
                        cannot be undone.
                    </p>
                </div>
            </div>
        </div>
        <div className="mt-5 sm:mt-4 sm:flex sm:flex-row-reverse">
            <Button onClick={on_delete} disabled={isLoading} danger={True}>
                Delete
            </Button>
            <Button onClick={onClose} disabled={isLoading} secondary={True}>
                Cancel
            </Button>
        </div>
    </Modal>
}

