def detectTypeFromKG(type: str = "") -> any {
    t = type.lower();
    if (("film" in t) or ("movie" in t)) {
        return "movie";
    }
    if ((("tv" in t) or ("series" in t)) or ("show" in t)) {
        return "show";
    }
    if (((("actor" in t) or ("actress" in t)) or ("person" in t)) or ("director" in t)) {
        return "person";
    }
    return "movie";
}

def detectTypeFromSnippet(text: str) -> any {
    t = text.lower();
    if (("imdb" in t) and ("rating" in t)) {
        return "review";
    }
    if (("cast" in t) or ("poster" in t)) {
        return "movie";
    }
    return "movie";
}

