def:pub xlCount(level: float) -> int {
    xlCandy = 0;
    i = min(level, 50.0);
    while i > 40.0 {
        if i >= 48.5 {
            xlCandy += 20;
        } elif i >= 46.5 {
            xlCandy += 17;
        } elif i >= 44.5 {
            xlCandy += 15;
        } elif i >= 42.5 {
            xlCandy += 12;
        } else {
            xlCandy += 10;
        }
        i -= 0.5;
    }
    return xlCandy;
}

