glob:pub BANNED_RING_COLOR: str = "#ef4444";

glob MIN_RADIUS: int = 3;

glob MAX_RADIUS: int = 7;

glob RADIUS_CEILING_BYTES: int = 1000000;

glob REFUSED_STATUS_CODES: set[int] = {401, 403, 429, 444};

def:pub statusClass(code: float | None) -> str {
    if (not isinstance(code, (int, float))) {
        return "unknown";
    }
    if ((code >= 200) and (code < 300)) {
        return "2xx";
    }
    if ((code >= 300) and (code < 400)) {
        return "3xx";
    }
    if ((code >= 400) and (code < 500)) {
        return "4xx";
    }
    if ((code >= 500) and (code < 600)) {
        return "5xx";
    }
    return "unknown";
}

def:pub packetColor(status: str) -> str {
    return PACKET_COLORS[status];
}

def:pub packetRadius(bytes: float | None) -> float {
    if (not isinstance(bytes, (int, float)) or bytes <= 0) {
        return MIN_RADIUS;
    }
    scale = math.log10(bytes + 1) / math.log10(RADIUS_CEILING_BYTES + 1);
    radius = MIN_RADIUS + (MAX_RADIUS - MIN_RADIUS) * scale;
    return min(MAX_RADIUS, max(MIN_RADIUS, round(radius, 2)));
}

glob SEVERITY: dict[str, int] = {"unknown": 0, "2xx": 1, "3xx": 2, "4xx": 3, "5xx": 4};

