import from "@/shared/constants/responseTypes" { default as responseTypes }
import from "@/shared/lib/browser/bookmarks" { bm as bookmarks }

def isSameNode(id: str, destination: dict[str, object]) -> bool {
    parentId = destination.get("parentId");
    if parentId is None {
        parentId = "";
    }
    return id == str(parentId);
}

def moveBookmarkNodesAsync(
    ids: list[str],
    destination: dict[str, object],
    onDone: Callable[[str | None], None]
) {
    pending = len(ids);
    if pending == 0 {
        onDone(None);
        return;
    }
    errors: list[str] = [];
    for id in ids {
        bookmarks.move(
            id,
            destination,
            lambda (err: str | None, _data: object, _id: str = id) {
                if err {
                    errors.append(err);
                }
                pending -= 1;
                if pending == 0 {
                    if len(errors) > 0 {
                        onDone(errors[0]);
                    } else {
                        onDone(None);
                    }
                }
            }
        );
    }
}

def moveBookmarkNodeHandler(
    message: dict[str, object],
    sendResponse: Callable[[dict[str, object]], None]
) {
    data = message.get("data");
    if not data or not isinstance(data, dict) {
        sendResponse({"type": responseTypes.ERROR, "message": "Missing request data"});
        return;
    }
    idsVal = data.get("id");
    destination = data.get("destination");
    if not destination or not isinstance(destination, dict) {
        sendResponse({"type": responseTypes.ERROR, "message": "Missing destination"});
        return;
    }
    parentId = destination.get("parentId");
    if parentId is None or parentId == "" {
        sendResponse({"type": responseTypes.ERROR, "message": "Missing destination.parentId"});
        return;
    }
    ids: list[str] = [];
    if isinstance(idsVal, list) {
        ids = idsVal;
    } elif idsVal is not None {
        ids = [str(idsVal)];
    }
    ids = [id for id in ids if id is not None and id != ""];
    if len(ids) == 0 {
        sendResponse({"type": responseTypes.ERROR, "message": "No bookmark id provided"});
        return;
    }
    for nodeId in ids {
        if isSameNode(nodeId, destination) {
            sendResponse({"type": responseTypes.ERROR, "message": "You cannot move node into itself"});
            return;
        }
    }
    moveBookmarkNodesAsync(
        ids,
        destination,
        lambda (errMsg: str | None) {
            if errMsg {
                sendResponse({"type": responseTypes.ERROR, "message": errMsg});
            } else {
                sendResponse({
                    "type": responseTypes.SUCCESS,
                    "message": f"{len(ids)} item(s) moved"
                });
            }
        }
    );
}

