import from rules.css_properties {
    generateInlineStyleExtractFragment,
    generateParentStyleExtractFragment,
    generateStyleExtractFragment,
}
import from rules.scan_constants { SKIP_TAGS }

glob SKIP_OBJECT_LITERAL: str = ",".join([f"{t}:1" for t in SKIP_TAGS]);

def:pub buildScanScript(offset: int, limit: int) -> str {
    parentFragment = generateParentStyleExtractFragment();
    parentBlock = "";
    if parentFragment {
        parentBlock = f"""
    var pe = el.parentElement;
    var parent = null;
    if (pe) {{
      var pcs = getComputedStyle(pe);
      parent = {{
        computedStyles: {{
              {parentFragment}
        }}
      }};
    }}""";
    }

    inlineFragment = generateInlineStyleExtractFragment();
    inlineBlock = "";
    if inlineFragment {
        inlineBlock = f""",
      inlineStyles: {{
        {inlineFragment}
      }}""";
    }

    styleFragment = generateStyleExtractFragment();
    parentExpr = "parent" if parentFragment else "null";

    return f"""(function(offset, limit) {{
  var SKIP = {{{SKIP_OBJECT_LITERAL}}};
  if (!document.body) return {{ results: [], total: 0 }};
  var els = document.body.querySelectorAll('*');
  var total = els.length;
  var end = Math.min(offset + limit, total);
  var results = [];
  for (var i = offset; i < end; i++) {{
    var el = els[i];
    if (SKIP[el.tagName]) continue;
    var cs = getComputedStyle(el);
    if (cs.display === 'none') continue;
    var sel = el.tagName.toLowerCase();
    if (el.id) sel += '#' + CSS.escape(el.id);
    var cl = el.classList;
    for (var j = 0; j < cl.length && j < 3; j++) sel += '.' + CSS.escape(cl[j]);{parentBlock}
    results.push({{
      index: i,
      selector: sel,
      tagName: el.tagName.toLowerCase(),
      id: el.id || '',
      classList: Array.from(el.classList),
      computedStyles: {{
        {styleFragment}
      }},
      parent: {parentExpr}{inlineBlock}
    }});
  }}
  return {{ results: results, total: total }};
}})({offset}, {limit})""";
}

