import re;

obj SearchFilter {
    has type: str;
    has value: str;
}

obj ParsedSearchQuery {
    has text: str;
    has filters: list[SearchFilter];
}

glob VALID_MODULES: list[str] = ["notes", "tasks", "calendar", "docs"];

glob VALID_STATUSES: list[str] = ["done", "todo", "inprogress"];

glob VALID_DATES: list[str] = [
    "today", "thisweek", "overdue", "yesterday", "thismonth", "last7days", "last30days"
];

def:pub parseSearchQuery(query: str) -> ParsedSearchQuery {
    filters: list[SearchFilter] = [];
    parts: list[str] = re.split(r'\s+', query);
    textParts: list[str] = [];
    for part in parts {
        if not part {
            continue;
        }
        lowerPart = part.lower();
        if lowerPart.startswith("tag:") and len(part) > 4 {
            filters.append(SearchFilter(type="tag", value=part[4:].lower()));
        } elif lowerPart.startswith("in:") and len(part) > 3 {
            value = part[3:].lower();
            if value in VALID_MODULES {
                filters.append(SearchFilter(type="module", value=value));
            } else {
                textParts.append(part);
            }
        } elif lowerPart.startswith("status:") and len(part) > 7 {
            value = part[7:].lower();
            if value in VALID_STATUSES {
                filters.append(SearchFilter(type="status", value=value));
            } else {
                textParts.append(part);
            }
        } elif lowerPart.startswith("date:") and len(part) > 5 {
            value = part[5:].lower();
            if value in VALID_DATES {
                filters.append(SearchFilter(type="date", value=value));
            } else {
                textParts.append(part);
            }
        } else {
            textParts.append(part);
        }
    }
    return ParsedSearchQuery(text=" ".join(textParts).strip(), filters=filters);
}

def:pub getFiltersOfType(filters: list[SearchFilter], type: str) -> list[str] {
    return [f.value for f in filters if f.type == type];
}

def:pub formatFilter(filter: SearchFilter) -> str {
    match filter.type {
        case "tag":
            return f"tag:{filter.value}";
        case "module":
            return f"in:{filter.value}";
        case "status":
            return f"status:{filter.value}";
        case "date":
            return f"date:{filter.value}";
        case _:
            return f"{filter.type}:{filter.value}";
    }
}

