    try {
        await fetch(
            "/.netlify/functions/contactForm",
            method="POST",
            headers={"Content-Type": "application/json"},
            body=json.dumps({
                "name": post_data.name,
                "email": post_data.email,
                "message": post_data.message,
            }),
        );
        return True;
    } except Exception {
        return False;
    }
}

