def:pub useGravity(onUpdate: any) -> None {
    console.log("useGravity");
    update = lambda () -> any { DeviceMotion.setUpdateInterval(200); };
    subscribe = lambda () -> any { DeviceMotion.addListener(lambda (devicemotionData: any) -> any { onUpdate({"x": devicemotionData.rotation.gamma, "y": devicemotionData.rotation.beta}); }); update(); };
    unsubscribe = lambda () -> any { DeviceMotion.removeAllListeners(); };
    useEffect(lambda () -> any { subscribe(); return lambda () -> any { unsubscribe(); }; }, []);
}

glob GRAVITY_DISTANCE = 3;

def:pub useNormalizedGravity() -> any {
    _jx_d0: any = useState({"x": 0, "y": 0});
    value = _jx_d0[0];
    setValue = _jx_d0[1];
    useGravity(lambda (updated: any) -> any { clampedX = clamp((updated.x + (GRAVITY_DISTANCE / 2)), 0, GRAVITY_DISTANCE); clampedY = clamp((updated.y + (GRAVITY_DISTANCE / 2)), 0, GRAVITY_DISTANCE); normalizedX = roundDigitsLength((clampedX / GRAVITY_DISTANCE), 2); normalizedY = roundDigitsLength((clampedY / GRAVITY_DISTANCE), 2); if ((value.x != normalizedX) or (value.y != normalizedY)) {     setValue({"x": normalizedX, "y": normalizedY}); } });
    return value;
}

