def on_room_disconnected(
    remove_local_audio_track: Callable[[], None],
    remove_local_video_track: Callable[[], None],
    _r: Room,
    error: TwilioError,
) {
    if error {
        console.log(error);
    }
    remove_local_audio_track();
    remove_local_video_track();
}

def:pub useHandleRoomDisconnection(
    room: Room | None,
    remove_local_audio_track: Callable[[], None],
    remove_local_video_track: Callable[[], None],
) {
    useEffect(lambda {
        if room {
            handler = lambda (_r: Room, error: TwilioError) {
                on_room_disconnected(
                    remove_local_audio_track,
                    remove_local_video_track,
                    _r,
                    error,
                );
            };
            room.on("disconnected", handler);
            return lambda {
                room.off("disconnected", handler);
            };
        }
    }, [room, remove_local_audio_track, remove_local_video_track]);
}

