type DialogState = str | bool | None;
type DialogSetter = Callable[[DialogState], None];

def:pub useDialogState(initialState: DialogState = None) -> list[DialogState | DialogSetter] {
    state = useState(initialState);
    open = state[0];
    _setOpen = state[1];
    setOpen = lambda (value: DialogState) -> None {
        _setOpen(lambda (prev: DialogState) -> DialogState {
            return None if prev == value else value;
        });
    };
    return [open, setOpen];
}

