import from "react" { useState, useEffect }

def:pub useCopy(text: str, delay: int = 2000) -> dict[str, str | Callable[[], None] | bool] {
    _copied_state = useState(False);
    copied = _copied_state[0];
    setCopied = _copied_state[1];

    def copy() {
        navigator.clipboard.writeText(text);
        setCopied(True);
    }

    useEffect(lambda {
        if copied {
            timeout = setTimeout(lambda { setCopied(False); }, delay);
            return lambda { clearTimeout(timeout); };
        }
        return lambda { };
    }, [delay, copied]);

    return {"text": text, "copy": copy, "copied": copied};
}

