# Jac lang
# from: travisjneuman__neumanos::components/SearchHighlight.tsx
import from "../utils/fuzzySearch" { getHighlightSegments }

type HighlightSegment = {text: str, isMatch: bool};

def:pub SearchHighlight(text: str, matchedIndices: list[int] | None = None) -> JsxElement {
    if not matchedIndices or len(matchedIndices) == 0 {
        return <>{text}</>;
    }
    segments: list[HighlightSegment] = getHighlightSegments(text, matchedIndices) as list[HighlightSegment];
    <>
        {for (i, segment) in enumerate(segments) {
            if segment["isMatch"] {
                <mark key={str(i)} className="bg-accent-yellow/30 text-inherit rounded-sm px-0">{segment["text"]}</mark>
            } else {
                <>{segment["text"]}</>
            }
        }}
    </>
}

