# Language: Jac
# from: stasstepv__hermes-pwa::core/src/domain/mcp.ts
obj McpServer {
    has name: str;
    has enabled: bool;
    has type: str | None = None;
    has tools: float | None = None;
}

def toMcpServer(raw: dict[str, object]) -> McpServer {
    type_val = raw.get("type");
    tools_val = raw.get("tools");
    return McpServer(
        name=str(raw.get("name", raw.get("id", "MCP Server"))),
        enabled=raw.get("enabled") is True or raw.get("active") is True,
        type=type_val if isinstance(type_val, str) else None,
        tools=tools_val if isinstance(tools_val, (int, float)) else None,
    );
}

