import from "@/util" { validateJson }

glob ID_REF = "${id}";

def validateContrib(contribPoint: dict[str, object], contrib: object, ctx: dict[str, object]) {
    manifestInfo = contribPoint["manifestInfo"] as dict[str, object];
    validateJson(manifestInfo["schema"], contrib, ("contribution to point " + f"'{contribPoint['id']}' from extension '{ctx['extensionId']}'"));
}

def registerActivationEvents(contribPoint: dict[str, object], contrib: object, ctx: dict[str, object]) {
    codeInfo = contribPoint["codeInfo"];
    if not codeInfo {
        return;
    }
    codeInfoDict = codeInfo as dict[str, object];
    activationEvent = codeInfoDict["activationEvent"];
    if not activationEvent {
        return;
    }
    activationEventStr = activationEvent as str;
    if not (ID_REF in activationEventStr) {
        activationEvents = ctx["activationEvents"] as set[str];
        activationEvents.add(activationEventStr);
        return;
    }
}

