def:pub areMessageBubblePropsEqual(prev: MessageBubbleProps, next: MessageBubbleProps) -> bool {
    return (
        (prev.message == next.message)
        and (prev.rpc == next.rpc)
        and (prev.isLast == next.isLast)
        and (prev.streaming == next.streaming)
        and (prev.liveStatus == next.liveStatus)
        and (prev.liveFace == next.liveFace)
        and (prev.pendingApprovals == next.pendingApprovals)
        and (prev.activeSessionIds == next.activeSessionIds)
    );
}

def _markdown_anchor(props: dict[str, object]) -> object {
    href = props["href"];
    children = props["children"];
    attrs = {k: v for (k, v) in props.items() if k not in ["href", "children"]};
    return createElement(
        "a",
        {**attrs, "href": href, "target": "_blank", "rel": "noopener noreferrer"},
        children,
    );
}

