import from "styled-system" { FlexboxProps }
import from "../../utils/jsx" { cleanChildren, hasProps }
import from "../primitives/Box" { default as Box, BoxProps, PolymorphicComponent }

def getChildren(children: any) -> any {
    style = {"marginLeft": 0, "marginTop": 0};
    if not children {
        return None;
    }
    if isinstance(children, str) {
        return children;
    }
    if Array.isArray(children) {
        return cleanChildren(children).map(lambda (c: any, i: any) -> any { return cloneElement(c, {**({"style": style} if (i == 0) else {})}); });
    }
    if hasProps(children) {
        return cloneElement(children, {"style": style});
    }
    return children;
}

