    has applyDarkModeUseCase: ApplyDarkModeUseCase;
    has browser_window: Window;
    has preferredColorScheme: PreferredColorScheme postinit;
    has isDarkMode: bool postinit;

    def postinit {
        self.preferredColorScheme = PreferredColorScheme(
            browser_window=self.browser_window
        );
        self.isDarkMode = self.preferredColorScheme.isDarkMode;
