    if rotate is not None and rotate != "none" {
        return True;
    }
    scale = styles.get("scale");
    if scale is not None and scale != "none" {
        return True;
    }
    translate = styles.get("translate");
    if translate is not None and translate != "none" {
        return True;
    }
    filter_val = styles.get("filter");
    if filter_val is not None and filter_val != "none" {
        return True;
    }
    backdropFilter = styles.get("backdropFilter");
    if backdropFilter is not None and backdropFilter != "none" and backdropFilter != "" {
        return True;
    }
    perspective = styles.get("perspective");
    if perspective is not None and perspective != "none" {
        return True;
    }
    clipPath = styles.get("clipPath");
    if clipPath is not None and clipPath != "none" {
        return True;
    }
    if styles.get("isolation") == "isolate" {
        return True;
    }
    mixBlendMode = styles.get("mixBlendMode");
    if mixBlendMode is not None and mixBlendMode != "normal" {
        return True;
    }
    mask = styles.get("mask");
    if mask is not None and mask != "none" and mask != "" {
        return True;
    }
    containerType = styles.get("containerType");
    if containerType is not None and containerType != "normal" {
        return True;
    }
    offsetPath = styles.get("offsetPath");
    if offsetPath is not None and offsetPath != "none" {
        return True;
    }
    contentVisibility = styles.get("contentVisibility");
    if contentVisibility == "auto" or contentVisibility == "hidden" {
        return True;
    }
    if styles.get("transformStyle") == "preserve-3d" {
        return True;
    }
    contain = styles.get("contain", "");
    if CONTAIN_RE.search(contain) is not None {
        return True;
    }
    willChange = styles.get("willChange", "auto");
    if WILL_CHANGE_RE.search(willChange) is not None {
