    }
}

obj Unary(Node) {
    has op: UnaryOp;
    has arg: Node;
    def eval(ctx: EvalContext) -> object {
        return self.op(self.arg.eval(ctx));
    }
    def toString() -> str {
        op_name = self.op.__name__.lower();
        return f"{op_name}({self.arg.toString()})";
    }
}

obj Binary(Node) {
    has op: BinaryOp;
    has arg1: Node;
    has arg2: Node;
    def eval(ctx: EvalContext) -> object {
        x = self.arg1.eval(ctx);
        y = self.arg2.eval(ctx);
        return self.op(x, y);
    }
    def toString() -> str {
        op_name = self.op.__name__.lower();
        return f"{op_name}({self.arg1.toString()}, {self.arg2.toString()})";
    }
}

obj Conditional(Node) {
    has arg1: Node;
    has arg2: Node;
    has arg3: Node;
    def eval(ctx: EvalContext) -> object {
        condition = not not self.arg1.eval(ctx);
        if condition {
            return self.arg2.eval(ctx);
        }
        return self.arg3.eval(ctx);
    }
    def toString() -> str {
        return f"cond({self.arg1.toString()}, {self.arg2.toString()}, {self.arg3.toString()})";
    }
}

obj FunctionCall(Node) {
    has func: Node;
    has args: list[Node];
    def eval(ctx: EvalContext) -> object {
        fn = self.func.eval(ctx);
        values = [arg.eval(ctx) for arg in self.args];
        return (fn as Func)(*values);
    }
    def toString() -> str {
        arg_text = ", ".join([a.toString() for a in self.args]);
