def:pub getOptions(options: list[any], randomize: bool) -> any {
    opts = (options or []);
    if randomize {
        opts = shuffleArray(opts);
    }
    return opts;
}

def:pub getOptionFromConfig(option: any | list[any], config: any, multiple: bool) -> any {
    opt: any = option;
    if not config {
        return opt;
    }
    if config.value {
        if (multiple and Array.isArray(option)) {
            value: list[any] = [];
            for item in option {
                if isObject(item) {
                    value.append(get(item, config.value));
                }
                else {
                    value.append(item);
                }
            }
            opt = value;
        }
        else {
            opt = get(option, config.value);
        }
    }
    return opt;
}

