type StateListener[T] = Callable[[T | None, T], None];

obj Listener[T] {
    has listeners: set[StateListener[T]] = set();

    def size() -> int {
        return len(self.listeners);
    }

    def subscribe(listener: StateListener[T]) -> Callable[[], None] {
        self.listeners.add(listener);
        return lambda {
            if listener in self.listeners {
                self.listeners.discard(listener);
            }
        };
    }

    def notify(prev: T | None, next: T) {
        for listener in self.listeners {
            listener(prev, next);
        }
    }
}

