import from "@/components/ui" { Button, Checkbox, DialogBody, DialogClose, DialogContent, DialogFooter, DialogHeader, DialogTitle, Label }
import from "@/features/profile/lib/actions" { removeUser }
import from "aws-amplify/auth" { signOut }

def:pub DeleteAccountDialogContent(
    userId: str,
    onParentClose: Callable[[], None],
) -> JsxElement {
    has isChecked: bool = False;
    has isLoading: bool = False;

    def handleCancel() {
        onParentClose();
    }

    async def handleDelete() {
        if isLoading {
            return;
        }
        isLoading = True;
        result = await removeUser(userId);
        if not result.ok {
            alert("Something went wrong. Please try again.");
        } else {
            signOut();
            alert("Successfully deleted!");
        }
        isLoading = False;
    }

    def handleCheckboxChange() {
        isChecked = not isChecked;
    }

    <DialogContent>
        <DialogHeader>
            <DialogTitle>Delete account</DialogTitle>
        </DialogHeader>
        <DialogBody className="pt-6 pb-9">
            <div className="flex flex-col gap-9 text-left">
                <p>Are you sure you want to delete account?</p>
                <div className="flex items-center gap-3 justify-center">
                    <Checkbox
                        id="delete-account-confirm"
                        checked={isChecked}
                        onCheckedChange={handleCheckboxChange}
                    />
                    <Label htmlFor="delete-account-confirm">Yes, I want to delete my account</Label>
                </div>
            </div>
        </DialogBody>
        <DialogFooter>
            <DialogClose asChild>
                <Button variant="cancel" size="sm" onClick={handleCancel}>
                    Cancel
                </Button>
            </DialogClose>
            <Button
                variant="danger"
                size="sm"
                onClick={handleDelete}
                disabled={not isChecked or isLoading}
            >
                Delete
            </Button>
        </DialogFooter>
    </DialogContent>
}

