def arrowPathAndTriangle(task: ScaledArrowTask) -> list[str | float] {
    taskToEndPosition = 16.0;
    endY = task.x2 - 32;
    textX = task.x1 + 20;
    textY = task.y + taskToEndPosition;
    if task.y > 0 or task.y < 0 {
        path = f"\n      M {task.x1 + 18} {16}\n      v {task.y}\n      h {endY - task.x1 + 16}\n    ";
    } else {
        path = f"\n      M {task.x1 + 18} {16}\n      h {endY - task.x1 - 2}\n    ";
    }
    return [path, textX, textY];
}

def:pub ScaledArrow(taskFrom: ScaledArrowTask, dashed: float) -> JsxElement {
    arrowResult = arrowPathAndTriangle(taskFrom);
    path = arrowResult[0] as str;
    textX = arrowResult[1] as float;
    textY = arrowResult[2] as float;
    trianglePoints = "";
    extraLines: list[JsxElement] = [];
    textStyle: dict[str, str] = {"fontSize": "12px", "fontWeight": "normal"};

    if dashed > taskFrom.x2 {
        x1 = taskFrom.x2;
        x2 = dashed;
        if taskFrom.y == 0 {
            x1 = taskFrom.x2 - 18;
            x2 = dashed - 18;
        }
        extraLines.append(
            <line key={getUuid()} strokeWidth="1.5" x1={x1} y1={taskFrom.y + 16} x2={x2} y2={taskFrom.y + 16} strokeDasharray="2 2" />
        );
        if taskFrom.y > 0 {
            trianglePoints = f"{x2},32\n{x2 + 5},{37}\n{x2 - 5},{37}";
            extraLines.append(
                <line key={getUuid()} strokeWidth="1.5" x1={x2} y1={taskFrom.y + 16} x2={x2} y2={32} strokeDasharray="2 2" />
            );
        } elif taskFrom.y < 0 {
            trianglePoints = f"{x2},0\n{x2 + 5},{-5}\n{x2 - 5},{-5}";
            extraLines.append(
                <line key={getUuid()} strokeWidth="1.5" x1={x2} y1={taskFrom.y + 16} x2={x2} y2={0} strokeDasharray="2 2" />
            );
        }
    } elif dashed == taskFrom.x2 {
        trianglePoints = f"{taskFrom.x2 - 16},16\n{taskFrom.x2 - 16 - 5},{11}\n{taskFrom.x2 - 16 - 5},{21}";
        if taskFrom.y > 0 {
            x2 = dashed;
            extraLines.append(
                <line key={getUuid()} strokeWidth="1.5" x1={x2} y1={taskFrom.y + 16} x2={x2} y2={32} />
            );
        }
    }

    <g className="arrow" fill="grey" stroke="grey">
        <text key={getUuid()} x={textX} y={textY - 3} style={textStyle}>{taskFrom.name}</text>
        <text key={getUuid()} x={textX} y={textY + 13} style={textStyle}>{f"{taskFrom.duration}天"}</text>
        <path key={getUuid()} strokeWidth="1.5" d={path} fill="none" />
        {[line for line in extraLines]}
        <polygon points={trianglePoints} />
