import from "@/core/store" { getStoreRecord, setStoreRecord }
import from "@/util/disposable" { Disposable }

def:pub registerCodeContribution[T](
    contribPointId: str,
    contribId: str,
    contribValue: T
) -> Disposable {
    contribDataMap = getStoreRecord("codeContributions", contribPointId);
    if contribDataMap {
        existing = contribDataMap.get(contribId);
        if existing is contribValue {
            return Disposable(lambda { });
        }
        contribDataMap = dict(contribDataMap);
    } else {
        contribDataMap = {};
    }
    contribDataMap[contribId] = contribValue;
    setStoreRecord("codeContributions", contribPointId, contribDataMap);
    return Disposable(lambda {
        dataMap = getStoreRecord("codeContributions", contribPointId);
        if dataMap {
            dataMap.pop(contribId, None);
        }
    });
}

