import from "date-fns" { isSameDay, eachDayOfInterval, parseISO, addDays, addWeeks, addMonths, addYears, differenceInMilliseconds, isBefore, isAfter, startOfDay }

type DateInput = str | object;

def _getDay(date: object) -> int {
    return getattr(date, "getDay")() as int;
}

def:pub getDaysBetween(start: DateInput, end: DateInput) -> list[object] {
    startDate = parseISO(start) if isinstance(start, str) else start;
    endDate = parseISO(end) if isinstance(end, str) else end;
    return eachDayOfInterval({"start": startDate, "end": endDate});
}

def:pub isSameCalendarDay(date1: DateInput, date2: DateInput) -> bool {
    d1 = parseISO(date1) if isinstance(date1, str) else date1;
    d2 = parseISO(date2) if isinstance(date2, str) else date2;
    return isSameDay(d1, d2);
}

def:pub getWeekDays(weekStart: object) -> list[object] {
    return [addDays(weekStart, i) for i in range(7)];
}

def:pub snapToGrid(minutes: float, interval: float) -> float {
    units = round(minutes / interval) as int;
    return units * interval;
}

glob DAY_MAP: dict[str, int] = {"SU": 0, "MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6};

def advanceDate(date: object, frequency: str, interval: int) -> object {
    switch frequency {
        case "DAILY":
            return addDays(date, interval);
        case "WEEKLY":
            return addWeeks(date, interval);
        case "MONTHLY":
            return addMonths(date, interval);
        case "YEARLY":
            return addYears(date, interval);
        default:
            return date;
    }
}

def matchesByDay(date: object, byDay: list[str]) -> bool {
    dow = _getDay(date);
    return any(DAY_MAP[d.upper()] == dow for d in byDay);
}

