def:pub sumObjectsByKey(objs: list[dict[str, int]]) -> dict[str, int] {
    result: dict[str, int] = {};
    for obj in objs {
        for (k, v) in obj.items() {
            result[k] = (result.get(k, 0) or 0) + v;
        }
    }
    return result;
}

