# from: travisjneuman__neumanos::workers/analyticsWorker.ts
obj ActivityEvent {
    has timestamp: str;
    has module: str;
}

def calculateDailyStats(events: list[ActivityEvent]) -> dict[str, int] {
    counts: dict[str, int] = {};
    for event in events {
        day = event.timestamp[0:10];
        counts[day] = counts.get(day, 0) + 1;
    }
    return counts;
}

def calculateModuleDistribution(events: list[ActivityEvent]) -> dict[str, int] {
    distribution: dict[str, int] = {};
    for event in events {
        module = event.module if event.module else "unknown";
        distribution[module] = distribution.get(module, 0) + 1;
    }
    return distribution;
}

def calculateProductivityScore(tasksCompleted: float, habitsDone: float, hoursTracked: float) -> int {
    taskScore = min(tasksCompleted / 20.0, 1.0) * 50.0;
    habitScore = min(habitsDone / 10.0, 1.0) * 30.0;
    hourScore = min(hoursTracked / 8.0, 1.0) * 20.0;
    return round(taskScore + habitScore + hourScore);
}

