    errorText: str | None = None,
    required: bool = False,
    invalid: bool = False,
    disabled: bool = False,
    size: Size = "md",
    optionalText: str | None = None,
    className: str | None = None,
    id: str | None = None,
    props: dict[str, object] = {},
    ref: Ref[HTMLDivElement] = Ref(),
) -> JsxElement {
    fieldId: str = id if id else "field";
    helperId: str | None = f"{fieldId}-helper" if helperText or errorText else None;
    enhancedChildren = children;
    if children {
        enhancedChildren = Children.map(children, lambda (child: object) -> object {
            if isValidElement(child) {
                elt = child as ReactElement;
                childProps = elt.props as dict[str, object];
                childSize = childProps.get("size");
                return cloneElement(elt, {
                    "id": fieldId,
                    "size": childSize if childSize else size,
                    "disabled": disabled or bool(childProps.get("disabled")),
                    "aria-invalid": invalid or bool(childProps.get("aria-invalid")),
                    "aria-describedby": helperId if helperId else childProps.get("aria-describedby"),
                    "aria-required": required or bool(childProps.get("aria-required")),
                });
            }
            return child;
        });
    }
    <div
        ref={ref}
        data-slot="field"
        data-invalid={invalid if invalid else None}
        data-disabled={disabled if disabled else None}
        className={cn(fieldStyles["container"], className)}
        {**props}
    >
        {if label {
            <div className={fieldStyles["labelRow"]}>
                <label htmlFor={fieldId} className={cn(fieldLabelVariants(size=size))}>
                    {label}
                    {if required {
                        <span className={fieldStyles["required"]}>*</span>
                    }}
                </label>
                {if optionalText {
                    <span className={fieldStyles["optional"]}>{optionalText}</span>
                }}
            </div>
        }}
        {enhancedChildren}
        {if invalid and errorText {
            <p id={helperId as str} className={cn(fieldStyles["errorText"], fieldHelperVariants(size=size))} role="alert">{errorText}</p>
        } elif helperText {
            <p id={helperId as str} className={cn(fieldHelperVariants(size=size))}>{helperText}</p>
        }}
    </div>
}

